pragma solidity 0.8.21;

//https://github.com/mudgen/diamond-2/blob/master/contracts/facets/DiamondLoupeFacet.sol

import {LibDiamond} from "contracts/libraries/LibDiamond.sol";
import {IDiamondLoupe} from "contracts/interfaces/IDiamondLoupe.sol";

/* solhint-disable no-inline-assembly */
contract DiamondLoupeFacet is IDiamondLoupe {
    // Diamond Loupe Functions
    ////////////////////////////////////////////////////////////////////
    /// These functions are expected to be called frequently by tools.
    //
    // struct Facet {
    //     address facetAddress;
    //     bytes4[] functionSelectors;
    // }
    /// @notice Gets all facets and their selectors.
    /// @return facets_ Facet
    function facets() external view override returns (Facet[] memory facets_) {
        LibDiamond.DiamondStorage storage ds = LibDiamond.diamondStorage();
        facets_ = new Facet[](ds.selectorCount);
        uint8[] memory numFacetSelectors = new uint8[](ds.selectorCount);
        uint256 numFacets;
        uint256 selectorIndex;
        // loop through function selectors
        for (uint256 slotIndex; selectorIndex < ds.selectorCount; slotIndex++) {
            bytes32 slot = ds.selectorSlots[slotIndex];
            for (uint256 selectorSlotIndex; selectorSlotIndex < 8; selectorSlotIndex++) {
                selectorIndex++;
                if (selectorIndex > ds.selectorCount) {
                    break;
                }
                bytes4 selector = bytes4(slot << (selectorSlotIndex << 5));
                address facetAddress_ = address(bytes20(ds.facets[selector]));
                bool continueLoop = false;
                for (uint256 facetIndex; facetIndex < numFacets; facetIndex++) {
                    if (facets_[facetIndex].facetAddress == facetAddress_) {
                        facets_[facetIndex].functionSelectors[numFacetSelectors[facetIndex]] = selector;
                        // probably will never have more than 256 functions from one facet contract
                        require(numFacetSelectors[facetIndex] < 255, ">256 fn");
                        numFacetSelectors[facetIndex]++;
                        continueLoop = true;
                        break;
                    }
                }
                if (continueLoop) {
                    continueLoop = false;
                    continue;
                }
                facets_[numFacets].facetAddress = facetAddress_;
                facets_[numFacets].functionSelectors = new bytes4[](ds.selectorCount);
                facets_[numFacets].functionSelectors[0] = selector;
                numFacetSelectors[numFacets] = 1;
                numFacets++;
            }
        }
        for (uint256 facetIndex; facetIndex < numFacets; facetIndex++) {
            uint256 numSelectors = numFacetSelectors[facetIndex];
            bytes4[] memory selectors = facets_[facetIndex].functionSelectors;
            // setting the number of selectors
            assembly {
                mstore(selectors, numSelectors)
            }
        }
        // setting the number of facets
        assembly {
            mstore(facets_, numFacets)
        }
    }

    /// @notice Gets all the function selectors supported by a specific facet.
    /// @param _facet The facet address.
    /// @return _facetFunctionSelectors The selectors associated with a facet address.
    function facetFunctionSelectors(address _facet) external view override returns (bytes4[] memory _facetFunctionSelectors) {
        LibDiamond.DiamondStorage storage ds = LibDiamond.diamondStorage();
        uint256 numSelectors;
        _facetFunctionSelectors = new bytes4[](ds.selectorCount);
        uint256 selectorIndex;
        // loop through function selectors
        for (uint256 slotIndex; selectorIndex < ds.selectorCount; slotIndex++) {
            bytes32 slot = ds.selectorSlots[slotIndex];
            for (uint256 selectorSlotIndex; selectorSlotIndex < 8; selectorSlotIndex++) {
                selectorIndex++;
                if (selectorIndex > ds.selectorCount) {
                    break;
                }
                bytes4 selector = bytes4(slot << (selectorSlotIndex << 5));
                address facet = address(bytes20(ds.facets[selector]));
                if (_facet == facet) {
                    _facetFunctionSelectors[numSelectors] = selector;
                    numSelectors++;
                }
            }
        }
        // Set the number of selectors in the array
        assembly {
            mstore(_facetFunctionSelectors, numSelectors)
        }
    }

    /// @notice Get all the facet addresses used by a diamond.
    /// @return facetAddresses_
    function facetAddresses() external view override returns (address[] memory facetAddresses_) {
        LibDiamond.DiamondStorage storage ds = LibDiamond.diamondStorage();
        facetAddresses_ = new address[](ds.selectorCount);
        uint256 numFacets;
        uint256 selectorIndex;
        // loop through function selectors
        for (uint256 slotIndex; selectorIndex < ds.selectorCount; slotIndex++) {
            bytes32 slot = ds.selectorSlots[slotIndex];
            for (uint256 selectorSlotIndex; selectorSlotIndex < 8; selectorSlotIndex++) {
                selectorIndex++;
                if (selectorIndex > ds.selectorCount) {
                    break;
                }
                bytes4 selector = bytes4(slot << (selectorSlotIndex << 5));
                address facetAddress_ = address(bytes20(ds.facets[selector]));
                bool continueLoop = false;
                for (uint256 facetIndex; facetIndex < numFacets; facetIndex++) {
                    if (facetAddress_ == facetAddresses_[facetIndex]) {
                        continueLoop = true;
                        break;
                    }
                }
                if (continueLoop) {
                    continueLoop = false;
                    continue;
                }
                facetAddresses_[numFacets] = facetAddress_;
                numFacets++;
            }
        }
        // Set the number of facet addresses in the array
        assembly {
            mstore(facetAddresses_, numFacets)
        }
    }

    /// @notice Gets the facet that supports the given selector.
    /// @dev If facet is not found return address(0).
    /// @param _functionSelector The function selector.
    /// @return facetAddress_ The facet address.
    function facetAddress(bytes4 _functionSelector) external view override returns (address facetAddress_) {
        LibDiamond.DiamondStorage storage ds = LibDiamond.diamondStorage();
        facetAddress_ = address(bytes20(ds.facets[_functionSelector]));
    }
}
"},"contracts/facets/ERC721Facet.sol":{"content":"// SPDX-License-Identifier: GPL-3.0-only
pragma solidity 0.8.21;

import {IERC721} from "@openzeppelin/contracts/token/ERC721/IERC721.sol";
import {IERC721Receiver} from "@openzeppelin/contracts/token/ERC721/IERC721Receiver.sol";

import {IDiamond} from "interfaces/IDiamond.sol";
import {Events} from "contracts/libraries/Events.sol";
import {Errors} from "contracts/libraries/Errors.sol";
import {STypes, SR} from "contracts/libraries/DataTypes.sol";
import {Modifiers} from "contracts/libraries/AppStorage.sol";
import {LibDiamond} from "contracts/libraries/LibDiamond.sol";
import {LibSRUtil} from "contracts/libraries/LibSRUtil.sol";

// import {console} from "contracts/libraries/console.sol";

contract ERC721Facet is Modifiers, IERC721 {
    /**
     * @dev Returns the number of tokens in ``owner``'s account.
     */
    function balanceOf(address owner) external view returns (uint256 balance) {
        if (owner == address(0)) revert Errors.ERC721InvalidOwner(address(0));

        address[] storage assets = s.assets;
        uint256 length = assets.length;
        for (uint256 i; i < length;) {
            STypes.ShortRecord[] memory shortRecords = IDiamond(payable(address(this))).getShortRecords(assets[i], owner);
            for (uint256 j; j < shortRecords.length;) {
                if (shortRecords[j].tokenId != 0) {
                    balance++;
                }
                unchecked {
                    j++;
                }
            }
            unchecked {
                ++i;
            }
        }
    }

    /**
     * @dev Returns whether `tokenId` exists.
     *
     * Tokens can be managed by their owner or approved accounts via {approve} or {setApprovalForAll}.
     *
     * Tokens start existing when they are minted (`_mint`),
     * and stop existing when they are burned (`_burn`).
     */
    function _exists(uint256 tokenId) internal view virtual returns (bool) {
        return _ownerOf(tokenId) != address(0);
    }

    /**
     * @dev Returns the owner of the `tokenId`. Does NOT revert if token doesn't exist
     */
    function _ownerOf(uint256 tokenId) internal view virtual returns (address) {
        return s.nftMapping[tokenId].owner;
    }

    /**
     * @dev Returns the owner of the `tokenId` token.
     *
     * Requirements:
     *
     * - `tokenId` must exist.
     */
    function ownerOf(uint256 tokenId) public view virtual returns (address) {
        address owner = _ownerOf(tokenId);
        if (owner == address(0)) revert Errors.ERC721NonexistentToken(tokenId);

        return owner;
    }

    /**
     * @dev Safely transfers `tokenId` token from `from` to `to`.
     *
     * Requirements:
     *
     * - `from` cannot be the zero address.
     * - `to` cannot be the zero address.
     * - `tokenId` token must exist and be owned by `from`.
     * - If the caller is not `from`, it must be approved to move this token by either {approve} or {setApprovalForAll}.
     * - If `to` refers to a smart contract, it must implement {IERC721Receiver-onERC721Received}, which is called upon a safe transfer.
     *
     * Emits a {Transfer} event.
     */
    function safeTransferFrom(address from, address to, uint256 tokenId) public virtual {
        safeTransferFrom(from, to, tokenId, "");
    }

    /**
     * @dev Safely transfers `tokenId` token from `from` to `to`, checking first that contract recipients
     * are aware of the ERC721 protocol to prevent tokens from being forever locked.
     *
     * Requirements:
     *
     * - `from` cannot be the zero address.
     * - `to` cannot be the zero address.
     * - `tokenId` token must exist and be owned by `from`.
     * - If the caller is not `from`, it must have been allowed to move this token by either {approve} or {setApprovalForAll}.
     * - If `to` refers to a smart contract, it must implement {IERC721Receiver-onERC721Received}, which is called upon a safe transfer.
     *
     * Emits a {Transfer} event.
     */
    function safeTransferFrom(address from, address to, uint256 tokenId, bytes memory data) public virtual {
        transferFrom(from, to, tokenId);

        if (!_checkOnERC721Received(from, to, tokenId, data)) revert Errors.ERC721InvalidReceiver(to);
    }

    /**
     * @dev Transfers `tokenId` token from `from` to `to`.
     *
     * WARNING: Note that the caller is responsible to confirm that the recipient is capable of receiving ERC721
     * or else they may be permanently lost. Usage of {safeTransferFrom} prevents loss, though the caller must
     * understand this adds an external call which potentially creates a reentrancy vulnerability.
     *
     * Requirements:
     *
     * - `from` cannot be the zero address.
     * - `to` cannot be the zero address.
     * - `tokenId` token must be owned by `from`.
     * - If the caller is not `from`, it must be approved to move this token by either {approve} or {setApprovalForAll}.
     *
     * Emits a {Transfer} event.
     */
    function transferFrom(address from, address to, uint256 tokenId) public {
        // @dev ensure the tokenId can be downcasted to 40 bits
        if (tokenId > type(uint40).max) revert Errors.InvalidTokenId();

        if (msg.sender != from && !s.isApprovedForAll[from][msg.sender] && msg.sender != s.getApproved[tokenId]) {
            revert Errors.ERC721InsufficientApproval(msg.sender, tokenId);
        }

        address owner = ownerOf(tokenId);
        if (owner != from) revert Errors.ERC721IncorrectOwner(from, tokenId, owner);

        if (to == address(0)) revert Errors.ERC721InvalidReceiver(address(0));

        // @dev If NFT does not exist, ERC721NonexistentToken() will trigger
        LibSRUtil.transferShortRecord(from, to, uint40(tokenId));

        delete s.getApproved[tokenId];

        emit Events.Transfer(from, to, tokenId);
    }

    /**
     * @dev Returns if the `operator` is allowed to manage all of the assets of `owner`.
     *
     * See {setApprovalForAll}
     */
    function isApprovedForAll(address owner, address operator) public view returns (bool) {
        return s.isApprovedForAll[owner][operator];
    }

    /**
     * @dev Gives permission to `to` to transfer `tokenId` token to another account.
     * The approval is cleared when the token is transferred.
     *
     * Only a single account can be approved at a time, so approving the zero address clears previous approvals.
     *
     * Requirements:
     *
     * - The caller must own the token or be an approved operator.
     * - `tokenId` must exist.
     *
     * Emits an {Approval} event.
     */
    function approve(address to, uint256 tokenId) external {
        // @dev ensure the tokenId can be downcasted to 40 bits
        if (tokenId > type(uint40).max) revert Errors.InvalidTokenId();

        address owner = _ownerOf(tokenId);
        if (to == owner) revert Errors.ERC721InvalidOperator(owner);
        if (msg.sender != owner && !isApprovedForAll(owner, msg.sender)) revert Errors.ERC721InvalidApprover(msg.sender);

        s.getApproved[tokenId] = to;

        emit Events.Approval(owner, to, tokenId);
    }

    /**
     * @dev Approve or remove `operator` as an operator for the caller.
     * Operators can call {transferFrom} or {safeTransferFrom} for any token owned by the caller.
     *
     * Requirements:
     *
     * - The `operator` cannot be the caller.
     *
     * Emits an {ApprovalForAll} event.
     */
    function setApprovalForAll(address operator, bool approved) external {
        if (msg.sender == operator) revert Errors.ERC721InvalidOperator(msg.sender);

        s.isApprovedForAll[msg.sender][operator] = approved;
        emit Events.ApprovalForAll(msg.sender, operator, approved);
    }

    /**
     * @dev Reverts if the `tokenId` has not been minted yet.
     */
    function _requireMinted(uint256 tokenId) internal view virtual {
        if (!_exists(tokenId)) revert Errors.ERC721NonexistentToken(tokenId);
    }

    /**
     * @dev Returns the account approved for `tokenId` token.
     *
     * Requirements:
     *
     * - `tokenId` must exist.
     */
    function getApproved(uint256 tokenId) external view returns (address operator) {
        _requireMinted(tokenId);
        return s.getApproved[tokenId];
    }

    /**
     * @notice Mints NFT for active shortRecord
     * @dev Minters can only mint their own shortRecords
     *
     * @param asset The market that will be impacted
     * @param shortRecordId Id of active shortRecord
     */
    function mintNFT(address asset, uint8 shortRecordId, uint16 shortOrderId)
        external
        isNotFrozen(asset)
        nonReentrant
        onlyValidShortRecord(asset, msg.sender, shortRecordId)
    {
        STypes.ShortRecord storage short = s.shortRecords[asset][msg.sender][shortRecordId];

        STypes.Order storage shortOrder = s.shorts[asset][shortOrderId];

        // @dev this is for transferShortRecord
        if (short.status == SR.PartialFill) {
            if (shortOrder.shortRecordId != shortRecordId || shortOrder.addr != msg.sender) revert Errors.InvalidShortOrder();
        } else {
            shortOrderId = 0;
        }

        if (short.tokenId != 0) revert Errors.AlreadyMinted();

        uint40 tokenId = s.tokenIdCounter;
        s.nftMapping[tokenId] = STypes.NFT({
            owner: msg.sender,
            assetId: s.asset[asset].assetId,
            shortRecordId: shortRecordId,
            shortOrderId: shortOrderId
        });

        short.tokenId = tokenId;

        // @dev never decreases
        s.tokenIdCounter += 1;
    }

    function tokenURI(uint256 id) public view virtual returns (string memory) {}

    /**
     * @dev Private function to invoke {IERC721Receiver-onERC721Received} on a target address.
     * The call is not executed if the target address is not a contract.
     *
     * @param from address representing the previous owner of the given token ID
     * @param to target address that will receive the tokens
     * @param tokenId uint256 ID of the token to be transferred
     * @param data bytes optional data to send along with the call
     * @return bool whether the call correctly returned the expected magic value
     */
    function _checkOnERC721Received(address from, address to, uint256 tokenId, bytes memory data) private returns (bool) {
        if (to.code.length > 0) {
            try IERC721Receiver(to).onERC721Received(msg.sender, from, tokenId, data) returns (bytes4 retval) {
                return retval == IERC721Receiver.onERC721Received.selector;
            } catch (bytes memory reason) {
                if (reason.length == 0) {
                    revert Errors.ERC721InvalidReceiver(to);
                } else {
                    /// @solidity memory-safe-assembly
                    // solhint-disable-next-line no-inline-assembly
                    assembly {
                        revert(add(32, reason), mload(reason))
                    }
                }
            }
        } else {
            return true;
        }
    }

    // This implements ERC-165 (copied from DiamondLoupeFacet.sol)
    function supportsInterface(bytes4 _interfaceId) external view returns (bool) {
        LibDiamond.DiamondStorage storage ds = LibDiamond.diamondStorage();
        return ds.supportedInterfaces[_interfaceId];
    }
}
"},"contracts/facets/ExitShortFacet.sol":{"content":"// SPDX-License-Identifier: GPL-3.0-only
pragma solidity 0.8.21;

import {U256, U80, U88} from "contracts/libraries/PRBMathHelper.sol";

import {IDiamond} from "interfaces/IDiamond.sol";

import {Modifiers} from "contracts/libraries/AppStorage.sol";
import {Errors} from "contracts/libraries/Errors.sol";
import {Events} from "contracts/libraries/Events.sol";
import {STypes, MTypes, SR} from "contracts/libraries/DataTypes.sol";
import {LibAsset} from "contracts/libraries/LibAsset.sol";
import {LibOrders} from "contracts/libraries/LibOrders.sol";
import {LibShortRecord} from "contracts/libraries/LibShortRecord.sol";
import {LibSRUtil} from "contracts/libraries/LibSRUtil.sol";

// import {console} from "contracts/libraries/console.sol";

contract ExitShortFacet is Modifiers {
    using U256 for uint256;
    using U80 for uint80;
    using U88 for uint88;
    using LibSRUtil for STypes.ShortRecord;
    using {LibAsset.burnMsgSenderDebt} for address;

    address private immutable dusd;

    constructor(address _dusd) {
        dusd = _dusd;
    }

    /**
     * @notice Exits a short using shorter's ERC in wallet (i.e.MetaMask)
     * @dev allows for partial exit via buybackAmount
     *
     * @param asset The market that will be impacted
     * @param id Id of short
     * @param buybackAmount Erc amount to buy back
     *
     */
    function exitShortWallet(address asset, uint8 id, uint88 buybackAmount, uint16 shortOrderId)
        external
        isNotFrozen(asset)
        nonReentrant
        onlyValidShortRecord(asset, msg.sender, id)
    {
        STypes.Asset storage Asset = s.asset[asset];
        STypes.ShortRecord storage short = s.shortRecords[asset][msg.sender][id];
        SR initialStatus = short.status;

        short.updateErcDebt(asset);
        uint256 ercDebt = short.ercDebt;
        if (buybackAmount > ercDebt || buybackAmount == 0) revert Errors.InvalidBuyback();

        asset.burnMsgSenderDebt(buybackAmount);
        Asset.ercDebt -= buybackAmount;
        // refund the rest of the collateral if ercDebt is fully paid back
        if (buybackAmount == ercDebt) {
            uint88 collateral = short.collateral;
            s.vaultUser[Asset.vault][msg.sender].ethEscrowed += collateral;
            LibSRUtil.disburseCollateral(asset, msg.sender, collateral, short.dethYieldRate, short.updatedAt);
            LibShortRecord.deleteShortRecord(asset, msg.sender, id);
        } else {
            short.ercDebt -= buybackAmount;
        }

        LibSRUtil.checkShortMinErc({
            asset: asset,
            initialStatus: initialStatus,
            shortOrderId: shortOrderId,
            shortRecordId: id,
            shorter: msg.sender
        });

        emit Events.ExitShortWallet(asset, msg.sender, id, buybackAmount);
    }

    /**
     * @notice Exits a short using shorter's ERC in balance (ErcEscrowed)
     * @dev allows for partial exit via buybackAmount
     *
     * @param asset The market that will be impacted
     * @param id Id of short
     * @param buybackAmount Erc amount to buy back
     *
     */
    function exitShortErcEscrowed(address asset, uint8 id, uint88 buybackAmount, uint16 shortOrderId)
        external
        isNotFrozen(asset)
        nonReentrant
        onlyValidShortRecord(asset, msg.sender, id)
    {
        STypes.Asset storage Asset = s.asset[asset];
        STypes.ShortRecord storage short = s.shortRecords[asset][msg.sender][id];
        SR initialStatus = short.status;

        short.updateErcDebt(asset);
        uint256 ercDebt = short.ercDebt;
        if (buybackAmount == 0 || buybackAmount > ercDebt) revert Errors.InvalidBuyback();

        {
            STypes.AssetUser storage AssetUser = s.assetUser[asset][msg.sender];
            if (AssetUser.ercEscrowed < buybackAmount) revert Errors.InsufficientERCEscrowed();

            AssetUser.ercEscrowed -= buybackAmount;
        }

        Asset.ercDebt -= buybackAmount;
        // refund the rest of the collateral if ercDebt is fully paid back
        if (ercDebt == buybackAmount) {
            uint88 collateral = short.collateral;
            s.vaultUser[Asset.vault][msg.sender].ethEscrowed += collateral;
            LibSRUtil.disburseCollateral(asset, msg.sender, collateral, short.dethYieldRate, short.updatedAt);

            LibShortRecord.deleteShortRecord(asset, msg.sender, id);
        } else {
            short.ercDebt -= buybackAmount;
        }

        LibSRUtil.checkShortMinErc({
            asset: asset,
            initialStatus: initialStatus,
            shortOrderId: shortOrderId,
            shortRecordId: id,
            shorter: msg.sender
        });

        emit Events.ExitShortErcEscrowed(asset, msg.sender, id, buybackAmount);
    }

    /**
     * @notice Exits a short by placing bid on market
     * @dev allows for partial exit via buybackAmount
     *
     * @param asset The market that will be impacted
     * @param id Id of short
     * @param buybackAmount Erc amount to buy back
     * @param price Price at which shorter wants to place bid
     * @param shortHintArray Array of hintId for the id to start matching against shorts since you can't match a short < oracle price
     *
     */
    function exitShort(
        address asset,
        uint8 id,
        uint88 buybackAmount,
        uint80 price,
        uint16[] memory shortHintArray,
        uint16 shortOrderId
    ) external isNotFrozen(asset) nonReentrant onlyValidShortRecord(asset, msg.sender, id) {
        MTypes.ExitShort memory e;
        e.asset = asset;
        LibOrders.updateOracleAndStartingShortViaTimeBidOnly(e.asset, shortHintArray);

        STypes.Asset storage Asset = s.asset[e.asset];
        STypes.ShortRecord storage short = s.shortRecords[e.asset][msg.sender][id];

        // @dev Must prevent forcedBid from exitShort() matching with original shortOrder
        e.shortOrderIsCancelled = LibSRUtil.checkCancelShortOrder({
            asset: asset,
            initialStatus: short.status,
            shortOrderId: shortOrderId,
            shortRecordId: id,
            shorter: msg.sender
        });

        short.updateErcDebt(e.asset);

        // @dev if short order was cancelled, fully exit
        e.buybackAmount = e.shortOrderIsCancelled ? short.ercDebt : buybackAmount;
        e.beforeExitCR = getCollateralRatioNonPrice(short);
        e.ercDebt = short.ercDebt;
        e.collateral = short.collateral;

        if (e.buybackAmount == 0 || e.buybackAmount > e.ercDebt) revert Errors.InvalidBuyback();

        {
            uint256 ethAmount = price.mul(e.buybackAmount);
            if (ethAmount > e.collateral) revert Errors.InsufficientCollateral();
        }

        // Temporary accounting to enable bid
        STypes.VaultUser storage VaultUser = s.vaultUser[Asset.vault][msg.sender];
        VaultUser.ethEscrowed += e.collateral;

        // Create bid with current msg.sender
        (e.ethFilled, e.ercAmountLeft) =
            IDiamond(payable(address(this))).createForcedBid(msg.sender, e.asset, price, e.buybackAmount, shortHintArray);
        if (e.ethFilled == 0) revert Errors.ExitShortPriceTooLow();
        e.ercFilled = e.buybackAmount - e.ercAmountLeft;
        Asset.ercDebt -= e.ercFilled;
        s.assetUser[e.asset][msg.sender].ercEscrowed -= e.ercFilled;

        // Refund the rest of the collateral if ercDebt is fully paid back
        if (e.ercDebt == e.ercFilled) {
            // Full Exit
            LibSRUtil.disburseCollateral(e.asset, msg.sender, e.collateral, short.dethYieldRate, short.updatedAt);
            LibShortRecord.deleteShortRecord(e.asset, msg.sender, id); // prevent reentrancy
        } else {
            short.collateral -= e.ethFilled;
            short.ercDebt -= e.ercFilled;
            if (short.ercDebt < LibAsset.minShortErc(asset)) revert Errors.CannotLeaveDustAmount();

            // @dev Only allow partial exit if the CR is same or better than before
            if (getCollateralRatioNonPrice(short) < e.beforeExitCR) revert Errors.PostExitCRLtPreExitCR();

            // @dev collateral already subtracted in exitShort()
            VaultUser.ethEscrowed -= e.collateral - e.ethFilled;
            LibSRUtil.disburseCollateral(e.asset, msg.sender, e.ethFilled, short.dethYieldRate, short.updatedAt);
        }
        emit Events.ExitShort(asset, msg.sender, id, e.ercFilled);
    }

    function getCollateralRatioNonPrice(STypes.ShortRecord storage short) internal view returns (uint256 cRatio) {
        return short.collateral.div(short.ercDebt);
    }
}
"},"contracts/facets/MarketShutdownFacet.sol":{"content":"// SPDX-License-Identifier: GPL-3.0-only
pragma solidity 0.8.21;

import {U256, U96, U88, U80} from "contracts/libraries/PRBMathHelper.sol";

import {Errors} from "contracts/libraries/Errors.sol";
import {Events} from "contracts/libraries/Events.sol";
import {F, STypes} from "contracts/libraries/DataTypes.sol";
import {Modifiers} from "contracts/libraries/AppStorage.sol";
import {LibAsset} from "contracts/libraries/LibAsset.sol";
import {LibOracle} from "contracts/libraries/LibOracle.sol";
import {LibOrders} from "contracts/libraries/LibOrders.sol";

// import {console} from "contracts/libraries/console.sol";

contract MarketShutdownFacet is Modifiers {
    using U256 for uint256;
    using U96 for uint96;
    using U88 for uint88;
    using U80 for uint80;
    using {LibAsset.burnMsgSenderDebt} for address;

    /**
     * @notice Freezes the market permanently when c-ratio threshold reached
     * @dev Market is closed and shorters lose access to their positions
     * @dev Excess collateral when c-ratio > 1 sent to TAPP
     *
     * @param asset The market that will be impacted
     */
    function shutdownMarket(address asset) external onlyAdminOrDAO onlyValidAsset(asset) isNotFrozen(asset) nonReentrant {
        STypes.Asset storage Asset = s.asset[asset];

        uint256 oraclePrice = LibOracle.getOraclePrice(asset);
        uint256 cRatio = Asset.dethCollateral.div(oraclePrice.mul(Asset.ercDebt));
        if (cRatio > LibAsset.penaltyCR(asset)) {
            revert Errors.SufficientCollateral();
        } else {
            LibOracle.setPriceAndTime(asset, oraclePrice, LibOrders.getOffsetTime());
            uint256 vault = Asset.vault;
            uint88 assetDethCollateral = Asset.dethCollateral;
            s.vault[vault].dethCollateral -= assetDethCollateral;
            Asset.frozen = F.Permanent;
            if (cRatio > 1 ether) {
                // More than enough collateral to redeem ERC 1:1, send extras to TAPP
                uint88 excessDeth = assetDethCollateral - assetDethCollateral.divU88(cRatio);
                s.vaultUser[vault][address(this)].ethEscrowed += excessDeth;
                // Reduces c-ratio to 1
                Asset.dethCollateral -= excessDeth;
            }
        }
        emit Events.ShutdownMarket(asset);
    }

    /**
     * @notice Allows user to redeem erc from their wallet and/or escrow at the oracle price of market shutdown
     * @dev Market must be permanently frozen, redemptions drawn from the combined collateral of all short records
     *
     * @param asset The market that will be impacted
     */
    function redeemErc(address asset, uint88 amtWallet, uint88 amtEscrow) external isPermanentlyFrozen(asset) nonReentrant {
        STypes.Asset storage Asset = s.asset[asset];

        if (amtWallet > 0) {
            asset.burnMsgSenderDebt(amtWallet);
        }

        if (amtEscrow > 0) {
            s.assetUser[asset][msg.sender].ercEscrowed -= amtEscrow;
        }

        uint88 amtErc = amtWallet + amtEscrow;
        // Discount redemption when asset is undercollateralized
        uint88 amtDeth = amtErc.mul(Asset.dethCollateral).divU88(Asset.ercDebt);
        s.vaultUser[Asset.vault][msg.sender].ethEscrowed += amtDeth;
        emit Events.RedeemErc(asset, msg.sender, amtWallet, amtEscrow);
    }
}
"},"contracts/facets/OrdersFacet.sol":{"content":"// SPDX-License-Identifier: GPL-3.0-only
pragma solidity 0.8.21;

import {U256, U88} from "contracts/libraries/PRBMathHelper.sol";

import {Modifiers} from "contracts/libraries/AppStorage.sol";
import {Errors} from "contracts/libraries/Errors.sol";
import {STypes, O} from "contracts/libraries/DataTypes.sol";
import {LibOrders} from "contracts/libraries/LibOrders.sol";
import {C} from "contracts/libraries/Constants.sol";

// import {console} from "contracts/libraries/console.sol";

contract OrdersFacet is Modifiers {
    using U256 for uint256;
    using U88 for uint88;
    using LibOrders for mapping(address => mapping(uint16 => STypes.Order));

    /**
     * @notice Cancels unfilled bid on market
     *
     * @param asset The market that will be impacted
     * @param id Id of bid
     */
    function cancelBid(address asset, uint16 id) external onlyValidAsset(asset) nonReentrant {
        STypes.Order storage bid = s.bids[asset][id];
        if (msg.sender != bid.addr) revert Errors.NotOwner();

        LibOrders.cancelBid(asset, id);
    }

    /**
     * @notice Cancels unfilled ask on market
     *
     * @param asset The market that will be impacted
     * @param id Id of ask
     */
    function cancelAsk(address asset, uint16 id) external onlyValidAsset(asset) nonReentrant {
        STypes.Order storage ask = s.asks[asset][id];
        if (msg.sender != ask.addr) revert Errors.NotOwner();

        LibOrders.cancelAsk(asset, id);
    }

    /**
     * @notice Cancels unfilled short on market
     *
     * @param asset The market that will be impacted
     * @param id Id of short
     */
    function cancelShort(address asset, uint16 id) external onlyValidAsset(asset) nonReentrant {
        STypes.Order storage short = s.shorts[asset][id];
        if (msg.sender != short.addr) revert Errors.NotOwner();

        LibOrders.cancelShort(asset, id);
    }

    /**
     * @notice Used to clear orderbook and/or to prevent DOS
     *
     * @param asset The market that will be impacted
     * @param orderType Order type to be cancelled
     * @param lastOrderId Id of the order in the last position, farthest from HEAD
     * @param numOrdersToCancel Number of orders to cancel, includinf the lastOrderId
     */
    function cancelOrderFarFromOracle(address asset, O orderType, uint16 lastOrderId, uint16 numOrdersToCancel)
        external
        onlyAdminOrDAO
        onlyValidAsset(asset)
        nonReentrant
    {
        if (s.asset[asset].orderIdCounter < 65000) revert Errors.OrderIdCountTooLow();

        if (numOrdersToCancel > 1000) revert Errors.CannotCancelMoreThan1000Orders();

        if (orderType == O.LimitBid && s.bids[asset][lastOrderId].nextId == C.TAIL) {
            cancelManyBids(asset, lastOrderId, numOrdersToCancel);
        } else if (orderType == O.LimitAsk && s.asks[asset][lastOrderId].nextId == C.TAIL) {
            cancelManyAsks(asset, lastOrderId, numOrdersToCancel);
        } else if (orderType == O.LimitShort && s.shorts[asset][lastOrderId].nextId == C.TAIL) {
            cancelManyShorts(asset, lastOrderId, numOrdersToCancel);
        } else {
            revert Errors.NotLastOrder();
        }
    }

    function cancelManyBids(address asset, uint16 lastOrderId, uint16 numOrdersToCancel) internal {
        uint16 prevId;
        uint16 currentId = lastOrderId;
        for (uint8 i; i < numOrdersToCancel;) {
            prevId = s.bids[asset][currentId].prevId;
            LibOrders.cancelBid(asset, currentId);
            currentId = prevId;
            unchecked {
                ++i;
            }
        }
    }

    function cancelManyAsks(address asset, uint16 lastOrderId, uint16 numOrdersToCancel) internal {
        uint16 prevId;
        uint16 currentId = lastOrderId;
        for (uint8 i; i < numOrdersToCancel;) {
            prevId = s.asks[asset][currentId].prevId;
            LibOrders.cancelAsk(asset, currentId);
            currentId = prevId;
            unchecked {
                ++i;
            }
        }
    }

    function cancelManyShorts(address asset, uint16 lastOrderId, uint16 numOrdersToCancel) internal {
        uint16 prevId;
        uint16 currentId = lastOrderId;
        for (uint8 i; i < numOrdersToCancel;) {
            prevId = s.shorts[asset][currentId].prevId;
            LibOrders.cancelShort(asset, currentId);
            currentId = prevId;
            unchecked {
                ++i;
            }
        }
    }
}
"},"contracts/facets/OwnerFacet.sol":{"content":"// SPDX-License-Identifier: GPL-3.0-only
pragma solidity 0.8.21;

import {U256} from "contracts/libraries/PRBMathHelper.sol";

import {Modifiers} from "contracts/libraries/AppStorage.sol";
import {Errors} from "contracts/libraries/Errors.sol";
import {Events} from "contracts/libraries/Events.sol";
import {STypes, MTypes} from "contracts/libraries/DataTypes.sol";
import {LibDiamond} from "contracts/libraries/LibDiamond.sol";
import {LibOrders} from "contracts/libraries/LibOrders.sol";
import {LibOracle} from "contracts/libraries/LibOracle.sol";
import {LibShortRecord} from "contracts/libraries/LibShortRecord.sol";
import {LibAsset} from "contracts/libraries/LibAsset.sol";
import {C} from "contracts/libraries/Constants.sol";

// import {console} from "contracts/libraries/console.sol";

contract OwnerFacet is Modifiers {
    using U256 for uint256;

    /**
     * @notice Initialize data for newly deployed market
     * @dev Single use only
     *
     * @param asset The market that will be impacted
     * @param a The market settings
     */

    /*
     * @param oracle The oracle for the asset
     * @param initialCR initialCR value of the new market
     * @param liquidationCR Liquidation ratio value of the new market
     * @param forcedBidPriceBuffer Liquidation limit value of the new market
     * @param penaltyCR Lowest threshold for shortRecord to not lose collateral during liquidation
     * @param tappFeePct Primary liquidation fee sent to TAPP out of shorter collateral
     * @param callerFeePct Primary liquidation fee sent to liquidator out of shorter collateral
     * @param minBidEth Minimum bid dust amount
     * @param minAskEth Minimum ask dust amount
     * @param minShortErc Minimum short record debt amount
     * @param recoveryCR CRatio threshold for recovery mode of the entire market
    */

    function createMarket(address asset, STypes.Asset memory a) external onlyDAO {
        STypes.Asset storage Asset = s.asset[asset];
        // can check non-zero ORDER_ID to prevent creating same asset
        if (Asset.orderIdCounter != 0) revert Errors.MarketAlreadyCreated();

        Asset.vault = a.vault;
        _setAssetOracle(asset, a.oracle);

        Asset.assetId = uint8(s.assets.length);
        s.assetMapping[Asset.assetId] = asset;
        s.assets.push(asset);

        STypes.Order memory headOrder;
        headOrder.prevId = C.HEAD;
        headOrder.id = C.HEAD;
        headOrder.nextId = C.TAIL;
        // @dev parts of OB depend on having sell's HEAD's price and creationTime = 0
        s.asks[asset][C.HEAD] = s.shorts[asset][C.HEAD] = headOrder;

        // @dev Using Bid's HEAD's order contain oracle data
        headOrder.creationTime = LibOrders.getOffsetTime();
        headOrder.ercAmount = uint80(LibOracle.getOraclePrice(asset));
        s.bids[asset][C.HEAD] = headOrder;

        // @dev hardcoded value
        Asset.orderIdCounter = C.STARTING_ID; // 100
        Asset.startingShortId = C.HEAD;

        // @dev comment with initial values
        _setInitialCR(asset, a.initialCR); // 170 -> 1.7 ether
        _setLiquidationCR(asset, a.liquidationCR); // 150 -> 1.5 ether
        _setForcedBidPriceBuffer(asset, a.forcedBidPriceBuffer); // 110 -> 1.1 ether
        _setPenaltyCR(asset, a.penaltyCR); // 110 -> 1.1 ether
        _setTappFeePct(asset, a.tappFeePct); // 25 -> .025 ether
        _setCallerFeePct(asset, a.callerFeePct); // 5 -> .005 ether
        _setMinBidEth(asset, a.minBidEth); // 10 -> 0.1 ether
        _setMinAskEth(asset, a.minAskEth); // 10 -> 0.1 ether
        _setMinShortErc(asset, a.minShortErc); // 2000 -> 2000 ether
        _setRecoveryCR(asset, a.recoveryCR); // 150 -> 1.5 ether

        // Create TAPP short
        LibShortRecord.createTappSR(asset);
        emit Events.CreateMarket(asset, Asset);
    }

    // @dev does not need read only reentrancy
    function owner() external view returns (address) {
        return LibDiamond.contractOwner();
    }

    function admin() external view returns (address) {
        return s.admin;
    }

    // @dev does not need read only reentrancy
    function ownerCandidate() external view returns (address) {
        return s.ownerCandidate;
    }

    function transferOwnership(address newOwner) external onlyDAO {
        s.ownerCandidate = newOwner;
        emit Events.NewOwnerCandidate(newOwner);
    }

    // @dev event emitted in setContractOwner
    function claimOwnership() external {
        if (s.ownerCandidate != msg.sender) revert Errors.NotOwnerCandidate();
        LibDiamond.setContractOwner(msg.sender);
        delete s.ownerCandidate;
    }

    //No need for claim step because DAO can also set admin
    function transferAdminship(address newAdmin) external onlyAdminOrDAO {
        s.admin = newAdmin;
        emit Events.NewAdmin(newAdmin);
    }

    function createVault(address deth, uint256 vault, MTypes.CreateVaultParams calldata params) external onlyDAO {
        if (s.dethVault[deth] != 0) revert Errors.VaultAlreadyCreated();
        s.dethVault[deth] = vault;
        _setTithe(vault, params.dethTithePercent);
        _setDittoMatchedRate(vault, params.dittoMatchedRate);
        _setDittoShorterRate(vault, params.dittoShorterRate);
        emit Events.CreateVault(deth, vault);
    }

    // Update eligibility requirements for yield accrual
    function setTithe(uint256 vault, uint16 dethTithePercent) external onlyAdminOrDAO {
        _setTithe(vault, dethTithePercent);
        emit Events.ChangeVaultSetting(vault);
    }

    function setDittoMatchedRate(uint256 vault, uint16 rewardRate) external onlyAdminOrDAO {
        _setDittoMatchedRate(vault, rewardRate);
        emit Events.ChangeVaultSetting(vault);
    }

    function setDittoShorterRate(uint256 vault, uint16 rewardRate) external onlyAdminOrDAO {
        _setDittoShorterRate(vault, rewardRate);
        emit Events.ChangeVaultSetting(vault);
    }

    // For Short Record collateral ratios
    // initialCR > liquidationCR > penaltyCR
    // After initial market creation. Set CRs from smallest to largest to prevent triggering the require checks

    function setInitialCR(address asset, uint16 value) external onlyAdminOrDAO {
        _setInitialCR(asset, value);
        emit Events.ChangeMarketSetting(asset);
    }

    function setLiquidationCR(address asset, uint16 value) external onlyAdminOrDAO {
        require(value > s.asset[asset].penaltyCR, "below penalty CR");
        _setLiquidationCR(asset, value);
        emit Events.ChangeMarketSetting(asset);
    }

    function setForcedBidPriceBuffer(address asset, uint8 value) external onlyAdminOrDAO {
        _setForcedBidPriceBuffer(asset, value);
        emit Events.ChangeMarketSetting(asset);
    }

    function setPenaltyCR(address asset, uint8 value) external onlyAdminOrDAO {
        _setPenaltyCR(asset, value);
        emit Events.ChangeMarketSetting(asset);
    }

    function setTappFeePct(address asset, uint8 value) external onlyAdminOrDAO {
        _setTappFeePct(asset, value);
        emit Events.ChangeMarketSetting(asset);
    }

    function setCallerFeePct(address asset, uint8 value) external onlyAdminOrDAO {
        _setCallerFeePct(asset, value);
        emit Events.ChangeMarketSetting(asset);
    }

    function setMinBidEth(address asset, uint8 value) external onlyAdminOrDAO {
        _setMinBidEth(asset, value);
        emit Events.ChangeMarketSetting(asset);
    }

    function setMinAskEth(address asset, uint8 value) external onlyAdminOrDAO {
        _setMinAskEth(asset, value);
        emit Events.ChangeMarketSetting(asset);
    }

    function setMinShortErc(address asset, uint16 value) external onlyAdminOrDAO {
        _setMinShortErc(asset, value);
        emit Events.ChangeMarketSetting(asset);
    }

    function setRecoveryCR(address asset, uint8 value) external onlyAdminOrDAO {
        _setRecoveryCR(asset, value);
        emit Events.ChangeMarketSetting(asset);
    }

    function createBridge(address bridge, uint256 vault, uint16 withdrawalFee) external onlyDAO {
        if (vault == 0) revert Errors.InvalidVault();
        STypes.Bridge storage Bridge = s.bridge[bridge];
        if (Bridge.vault != 0) revert Errors.BridgeAlreadyCreated();

        s.vaultBridges[vault].push(bridge);
        Bridge.vault = uint8(vault);
        _setWithdrawalFee(bridge, withdrawalFee);
        emit Events.CreateBridge(bridge, Bridge);
    }

    function setWithdrawalFee(address bridge, uint16 withdrawalFee) external onlyAdminOrDAO {
        _setWithdrawalFee(bridge, withdrawalFee);
        emit Events.ChangeBridgeSetting(bridge);
    }

    function _setAssetOracle(address asset, address oracle) private {
        if (asset == address(0) || oracle == address(0)) revert Errors.ParameterIsZero();
        s.asset[asset].oracle = oracle;
    }

    function _setTithe(uint256 vault, uint16 dethTithePercent) private {
        if (dethTithePercent > 33_33) revert Errors.InvalidTithe();
        // @dev dethTithePercent should never be changed outside of this function
        s.vault[vault].dethTithePercent = dethTithePercent;
    }

    function _setDittoMatchedRate(uint256 vault, uint16 rewardRate) private {
        require(rewardRate <= 100, "above 100");
        s.vault[vault].dittoMatchedRate = rewardRate;
    }

    function _setDittoShorterRate(uint256 vault, uint16 rewardRate) private {
        require(rewardRate <= 100, "above 100");
        s.vault[vault].dittoShorterRate = rewardRate;
    }

    function _setInitialCR(address asset, uint16 value) private {
        s.asset[asset].initialCR = value;
        require(LibAsset.initialCR(asset) < C.CRATIO_MAX, "above max CR");
    }

    function _setLiquidationCR(address asset, uint16 value) private {
        require(value > 100, "below 1.0");
        require(value <= 500, "above 5.0");
        s.asset[asset].liquidationCR = value;
    }

    function _setForcedBidPriceBuffer(address asset, uint8 value) private {
        require(value >= 100, "below 1.0");
        require(value <= 200, "above 2.0");
        s.asset[asset].forcedBidPriceBuffer = value;
    }

    function _setPenaltyCR(address asset, uint8 value) private {
        require(value >= 100, "below 1.0");
        require(value <= 120, "above 1.2");
        s.asset[asset].penaltyCR = value;
        require(LibAsset.penaltyCR(asset) < LibAsset.liquidationCR(asset), "above liquidation CR");
    }

    function _setTappFeePct(address asset, uint8 value) private {
        require(value > 0, "Can't be zero");
        require(value <= 250, "above 250");
        s.asset[asset].tappFeePct = value;
    }

    function _setCallerFeePct(address asset, uint8 value) private {
        require(value > 0, "Can't be zero");
        require(value <= 250, "above 250");
        s.asset[asset].callerFeePct = value;
    }

    function _setMinBidEth(address asset, uint8 value) private {
        //no upperboard check because uint8 max - 255
        require(value > 0, "Can't be zero");
        s.asset[asset].minBidEth = value;
    }

    function _setMinAskEth(address asset, uint8 value) private {
        //no upperboard check because uint8 max - 255
        require(value > 0, "Can't be zero");
        s.asset[asset].minAskEth = value;
    }

    function _setMinShortErc(address asset, uint16 value) private {
        //no upperboard check because uint8 max - 65,535
        require(value > 0, "Can't be zero");
        s.asset[asset].minShortErc = value;
    }

    function _setWithdrawalFee(address bridge, uint16 withdrawalFee) private {
        require(withdrawalFee <= 200, "above 2.00%");
        s.bridge[bridge].withdrawalFee = withdrawalFee;
    }

    function _setRecoveryCR(address asset, uint8 value) private {
        require(value >= 100, "below 1.0");
        require(value <= 200, "above 2.0");
        s.asset[asset].recoveryCR = value;
    }
}
"},"contracts/facets/PrimaryLiquidationFacet.sol":{"content":"// SPDX-License-Identifier: GPL-3.0-only
pragma solidity 0.8.21;

import {U256, U96, U88, U80} from "contracts/libraries/PRBMathHelper.sol";

import {IDiamond} from "interfaces/IDiamond.sol";

import {Errors} from "contracts/libraries/Errors.sol";
import {Events} from "contracts/libraries/Events.sol";
import {STypes, MTypes, SR} from "contracts/libraries/DataTypes.sol";
import {Modifiers} from "contracts/libraries/AppStorage.sol";
import {LibAsset} from "contracts/libraries/LibAsset.sol";
import {LibOrders} from "contracts/libraries/LibOrders.sol";
import {LibOracle} from "contracts/libraries/LibOracle.sol";
import {LibShortRecord} from "contracts/libraries/LibShortRecord.sol";
import {LibSRUtil} from "contracts/libraries/LibSRUtil.sol";
import {C} from "contracts/libraries/Constants.sol";

// import {console} from "contracts/libraries/console.sol";

contract PrimaryLiquidationFacet is Modifiers {
    using LibShortRecord for STypes.ShortRecord;
    using U256 for uint256;
    using U96 for uint96;
    using U88 for uint88;
    using U80 for uint80;

    address private immutable dusd;

    constructor(address _dusd) {
        dusd = _dusd;
    }

    /**
     * @notice Liquidates short by forcing shorter to place bid on market
     * @dev Primary liquidation method
     * @dev Shorter will bear the cost of forcedBid on market
     *
     * @param asset The market that will be impacted
     * @param shorter Shorter getting liquidated
     * @param id Id of short getting liquidated
     * @param shortHintArray Array of hintId for the id to start matching against shorts since you can't match a short < oracle price
     *
     * @return gasFee Estimated cost of gas for the forcedBid
     * @return ethFilled Amount of eth filled in forcedBid
     */
    function liquidate(address asset, address shorter, uint8 id, uint16[] memory shortHintArray, uint16 shortOrderId)
        external
        isNotFrozen(asset)
        nonReentrant
        onlyValidShortRecord(asset, shorter, id)
        returns (uint88, uint88)
    {
        if (msg.sender == shorter) revert Errors.CannotLiquidateSelf();
        // @dev TAPP partially reimburses gas fees, capped at 10 to limit arbitrary high cost
        if (shortHintArray.length > 10) revert Errors.TooManyHints();

        // @dev Ensures SR has enough ercDebt/collateral to make caller fee worthwhile
        LibSRUtil.checkCancelShortOrder({
            asset: asset,
            initialStatus: s.shortRecords[asset][shorter][id].status,
            shortOrderId: shortOrderId,
            shortRecordId: id,
            shorter: shorter
        });

        // @dev liquidate requires more up-to-date oraclePrice
        LibOrders.updateOracleAndStartingShortViaTimeBidOnly(asset, shortHintArray);

        MTypes.PrimaryLiquidation memory m = _setLiquidationStruct(asset, shorter, id, shortOrderId);

        // @dev Can liquidate as long as CR is low enough
        if (m.cRatio >= LibAsset.liquidationCR(m.asset)) {
            // If CR is too high, check for recovery mode and violation to continue liquidation
            if (!LibSRUtil.checkRecoveryModeViolation(m.asset, m.cRatio, m.oraclePrice)) revert Errors.SufficientCollateral();
        }

        // revert if no asks, or price too high
        _checklowestSell(m);

        _performForcedBid(m, shortHintArray);

        _liquidationFeeHandler(m);

        _fullorPartialLiquidation(m);

        emit Events.Liquidate(asset, shorter, id, msg.sender, m.ercDebtMatched);

        return (m.gasFee, m.ethFilled);
    }

    //PRIVATE FUNCTIONS

    // Reverts if no eligible sells, or if lowest sell price is too high
    // @dev startingShortId is updated via updateOracleAndStartingShortViaTimeBidOnly() prior to call
    function _checklowestSell(MTypes.PrimaryLiquidation memory m) private view {
        uint16 lowestAskKey = s.asks[m.asset][C.HEAD].nextId;
        uint16 startingShortId = s.asset[m.asset].startingShortId;
        uint256 bufferPrice = m.oraclePrice.mul(m.forcedBidPriceBuffer);
        if (
            // Checks for no eligible asks
            (lowestAskKey == C.TAIL || s.asks[m.asset][lowestAskKey].price > bufferPrice)
            // Checks for no eligible shorts
            && (
                startingShortId == C.HEAD // means no short >= oracleprice
                    || s.shorts[m.asset][startingShortId].price > bufferPrice
            )
        ) {
            revert Errors.NoSells();
        }
    }

    /**
     * @notice Sets the memory struct m with initial data
     *
     * @param asset The market that will be impacted
     * @param shorter Shorter getting liquidated
     * @param id Id of short getting liquidated
     *
     * @return m Memory struct used throughout PrimaryLiquidationFacet.sol
     */
    function _setLiquidationStruct(address asset, address shorter, uint8 id, uint16 shortOrderId)
        private
        returns (MTypes.PrimaryLiquidation memory)
    {
        LibShortRecord.updateErcDebt(asset, shorter, id);
        {
            MTypes.PrimaryLiquidation memory m;
            m.asset = asset;
            m.short = s.shortRecords[asset][shorter][id];
            m.shortOrderId = shortOrderId;
            m.vault = s.asset[asset].vault;
            m.shorter = shorter;
            m.penaltyCR = LibAsset.penaltyCR(asset);
            m.oraclePrice = LibOracle.getPrice(asset);
            m.cRatio = m.short.getCollateralRatio(m.oraclePrice);
            m.forcedBidPriceBuffer = LibAsset.forcedBidPriceBuffer(asset);
            m.callerFeePct = LibAsset.callerFeePct(m.asset);
            m.tappFeePct = LibAsset.tappFeePct(m.asset);
            m.ethDebt = m.short.ercDebt.mul(m.oraclePrice).mul(m.forcedBidPriceBuffer).mul(1 ether + m.tappFeePct + m.callerFeePct); // ethDebt accounts for forcedBidPriceBuffer and potential fees
            return m;
        }
    }

    /**
     * @notice Handles the set up and execution of making a forcedBid
     * @dev Shorter will bear the cost of forcedBid on market
     * @dev Depending on shorter's cRatio, the TAPP can attempt to fund bid
     *
     * @param m Memory struct used throughout PrimaryLiquidationFacet.sol
     * @param shortHintArray Array of hintId for the id to start matching against shorts since you can't match a short < oracle price
     *
     */
    function _performForcedBid(MTypes.PrimaryLiquidation memory m, uint16[] memory shortHintArray) private {
        uint256 startGas = gasleft();
        uint88 ercAmountLeft;

        // @dev Provide higher price to better ensure it can fully fill the liquidation
        uint80 _bidPrice = m.oraclePrice.mulU80(m.forcedBidPriceBuffer);

        // Shorter loses leftover collateral to TAPP when unable to maintain CR above the minimum
        m.loseCollateral = m.cRatio <= m.penaltyCR;

        // @dev Increase ethEscrowed by shorter's full collateral for forced bid
        STypes.VaultUser storage TAPP = s.vaultUser[m.vault][address(this)];
        TAPP.ethEscrowed += m.short.collateral;

        // Check ability of TAPP plus short collateral to pay back ethDebt
        if (TAPP.ethEscrowed < m.ethDebt) {
            STypes.Asset storage Asset = s.asset[m.asset];
            uint96 ercDebtPrev = m.short.ercDebt;
            if (Asset.ercDebt <= ercDebtPrev) {
                // Occurs when only one shortRecord in the asset (market)
                revert Errors.CannotSocializeDebt();
            }
            m.loseCollateral = true;
            // @dev Max ethDebt can only be the ethEscrowed in the TAPP
            m.ethDebt = TAPP.ethEscrowed;
            // Reduce ercDebt proportional to ethDebt
            m.short.ercDebt = uint88(m.ethDebt.div(_bidPrice.mul(1 ether + m.callerFeePct + m.tappFeePct))); // @dev(safe-cast)
            uint96 ercDebtSocialized = ercDebtPrev - m.short.ercDebt;
            // Update ercDebtRate to socialize loss (increase debt) to other shorts
            Asset.ercDebtRate += ercDebtSocialized.divU64(Asset.ercDebt - ercDebtPrev);
        }

        // @dev Liquidation contract will be the caller. Virtual accounting done later for shorter or TAPP
        (m.ethFilled, ercAmountLeft) =
            IDiamond(payable(address(this))).createForcedBid(address(this), m.asset, _bidPrice, m.short.ercDebt, shortHintArray);

        m.ercDebtMatched = m.short.ercDebt - ercAmountLeft;

        // @dev virtually burning the repurchased debt
        s.assetUser[m.asset][address(this)].ercEscrowed -= m.ercDebtMatched;
        s.asset[m.asset].ercDebt -= m.ercDebtMatched;

        uint256 gasUsed = startGas - gasleft();
        // @dev manually setting basefee to 1,000,000 in foundry.toml;
        // @dev By basing gasFee off of baseFee instead of priority, adversaries are prevent from draining the TAPP
        m.gasFee = uint88(gasUsed * block.basefee); // @dev(safe-cast)
    }

    /**
     * @notice Handles the distribution of liquidationFee
     * @dev liquidationFee is taken into consideration when determining black swan
     *
     * @param m Memory struct used throughout PrimaryLiquidationFacet.sol
     *
     */
    function _liquidationFeeHandler(MTypes.PrimaryLiquidation memory m) private {
        STypes.VaultUser storage VaultUser = s.vaultUser[m.vault][msg.sender];
        STypes.VaultUser storage TAPP = s.vaultUser[m.vault][address(this)];
        // distribute fees to TAPP and caller
        uint88 tappFee = m.ethFilled.mulU88(m.tappFeePct);
        uint88 callerFee = m.ethFilled.mulU88(m.callerFeePct) + m.gasFee;

        m.totalFee += tappFee + callerFee;
        // @dev TAPP already received the gasFee for being the forcedBid caller. tappFee nets out.
        if (TAPP.ethEscrowed >= callerFee) {
            TAPP.ethEscrowed -= callerFee;
            VaultUser.ethEscrowed += callerFee;
        } else {
            // Give caller (portion of?) tappFee instead of gasFee
            VaultUser.ethEscrowed += callerFee - m.gasFee + tappFee;
            m.totalFee -= m.gasFee;
            TAPP.ethEscrowed -= m.totalFee;
        }
    }

    function min88(uint256 a, uint88 b) private pure returns (uint88) {
        if (a > type(uint88).max) revert Errors.InvalidAmount();
        return a < b ? uint88(a) : b;
    }

    /**
     * @notice Handles accounting in event of full or partial liquidations
     *
     * @param m Memory struct used throughout PrimaryLiquidationFacet.sol
     *
     */
    function _fullorPartialLiquidation(MTypes.PrimaryLiquidation memory m) private {
        STypes.VaultUser storage TAPP = s.vaultUser[m.vault][address(this)];
        uint88 decreaseCol = min88(m.totalFee + m.ethFilled, m.short.collateral);

        if (m.short.ercDebt == m.ercDebtMatched) {
            // Full liquidation
            LibSRUtil.disburseCollateral(m.asset, m.shorter, m.short.collateral, m.short.dethYieldRate, m.short.updatedAt);
            LibShortRecord.deleteShortRecord(m.asset, m.shorter, m.short.id);
            if (!m.loseCollateral) {
                m.short.collateral -= decreaseCol;
                s.vaultUser[m.vault][m.shorter].ethEscrowed += m.short.collateral;
                TAPP.ethEscrowed -= m.short.collateral;
            }
        } else {
            // Partial liquidation
            m.short.ercDebt -= m.ercDebtMatched;
            m.short.collateral -= decreaseCol;
            s.shortRecords[m.asset][m.shorter][m.short.id] = m.short;

            TAPP.ethEscrowed -= m.short.collateral;
            LibSRUtil.disburseCollateral(m.asset, m.shorter, decreaseCol, m.short.dethYieldRate, m.short.updatedAt);

            // TAPP absorbs leftover short, unless it already owns the short
            if (m.loseCollateral && m.shorter != address(this)) {
                // Delete partially liquidated short
                LibShortRecord.deleteShortRecord(m.asset, m.shorter, m.short.id);
                // Absorb leftovers into TAPP short
                LibShortRecord.fillShortRecord(
                    m.asset,
                    address(this),
                    C.SHORT_STARTING_ID,
                    SR.FullyFilled,
                    m.short.collateral,
                    m.short.ercDebt,
                    s.asset[m.asset].ercDebtRate,
                    m.short.dethYieldRate
                );
            }
        }

        if (m.shorter != address(this)) {
            // Only relevant for non-TAPP SR
            LibSRUtil.checkShortMinErc({
                asset: m.asset,
                initialStatus: m.short.status,
                shortOrderId: m.shortOrderId,
                shortRecordId: m.short.id,
                shorter: m.shorter
            });
        }
    }
}
"},"contracts/facets/RedemptionFacet.sol":{"content":"// SPDX-License-Identifier: GPL-3.0-only
pragma solidity 0.8.21;

import {U256, U104, U88, U80, U64, U32} from "contracts/libraries/PRBMathHelper.sol";

import {Errors} from "contracts/libraries/Errors.sol";
import {Events} from "contracts/libraries/Events.sol";
import {Modifiers} from "contracts/libraries/AppStorage.sol";
import {STypes, MTypes, SR} from "contracts/libraries/DataTypes.sol";
import {LibAsset} from "contracts/libraries/LibAsset.sol";
import {LibShortRecord} from "contracts/libraries/LibShortRecord.sol";
import {LibSRUtil} from "contracts/libraries/LibSRUtil.sol";
import {LibOracle} from "contracts/libraries/LibOracle.sol";
import {LibOrders} from "contracts/libraries/LibOrders.sol";
import {LibBytes} from "contracts/libraries/LibBytes.sol";
import {C} from "contracts/libraries/Constants.sol";

import {SSTORE2} from "solmate/utils/SSTORE2.sol";
import {console} from "contracts/libraries/console.sol";

contract RedemptionFacet is Modifiers {
    using LibSRUtil for STypes.ShortRecord;
    using LibShortRecord for STypes.ShortRecord;
    using U256 for uint256;
    using U104 for uint104;
    using U88 for uint88;
    using U80 for uint80;
    using U64 for uint64;
    using U32 for uint32;

    function validRedemptionSR(STypes.ShortRecord storage shortRecord, address proposer, address shorter, uint256 minShortErc)
        internal
        view
        returns (bool)
    {
        // @dev Matches check in onlyValidShortRecord but with a more restrictive ercDebt condition
        // @dev Proposer can't redeem on self
        if (shortRecord.status == SR.Closed || shortRecord.ercDebt < minShortErc || proposer == shorter) {
            return false;
        } else {
            return true;
        }
    }

    /**
     * @notice Submit an array of SR as candidates for redemption, subject to dispute period
     * @dev Collateral and debt are immediately removed from the SR candidates
     * @dev Redemption Fee increases as more redemptions are proposed
     *
     * @param asset The market that will be impacted
     * @param proposalInput Array of data pertaining to the SR candidates
     * @param redemptionAmount Total amount of ercDebt requested to be redeemed
     * @param maxRedemptionFee Maximum fee that redeemer is willing to pay
     *
     */
    function proposeRedemption(
        address asset,
        MTypes.ProposalInput[] calldata proposalInput,
        uint88 redemptionAmount,
        uint88 maxRedemptionFee
    ) external isNotFrozen(asset) nonReentrant {
        if (proposalInput.length > type(uint8).max) revert Errors.TooManyProposals();
        MTypes.ProposeRedemption memory p;
        p.asset = asset;
        STypes.AssetUser storage redeemerAssetUser = s.assetUser[p.asset][msg.sender];
        uint256 minShortErc = LibAsset.minShortErc(p.asset);

        if (redemptionAmount < minShortErc) revert Errors.RedemptionUnderMinShortErc();

        if (redeemerAssetUser.ercEscrowed < redemptionAmount) revert Errors.InsufficientERCEscrowed();

        // @dev redeemerAssetUser.SSTORE2Pointer gets reset to address(0) after actual redemption
        if (redeemerAssetUser.SSTORE2Pointer != address(0)) revert Errors.ExistingProposedRedemptions();

        p.oraclePrice = LibOracle.getPrice(p.asset);

        bytes memory slate;
        for (uint8 i = 0; i < proposalInput.length; i++) {
            p.shorter = proposalInput[i].shorter;
            p.shortId = proposalInput[i].shortId;
            p.shortOrderId = proposalInput[i].shortOrderId;
            // @dev Setting this above _onlyValidShortRecord to allow skipping
            STypes.ShortRecord storage currentSR = s.shortRecords[p.asset][p.shorter][p.shortId];

            /// Evaluate proposed shortRecord

            if (!validRedemptionSR(currentSR, msg.sender, p.shorter, minShortErc)) continue;

            currentSR.updateErcDebt(p.asset);
            p.currentCR = currentSR.getCollateralRatio(p.oraclePrice);

            // @dev Skip if proposal is not sorted correctly or if above redemption threshold
            if (p.previousCR > p.currentCR || p.currentCR >= C.MAX_REDEMPTION_CR) continue;

            // @dev totalAmountProposed tracks the actual amount that can be redeemed. totalAmountProposed <= redemptionAmount
            if (p.totalAmountProposed + currentSR.ercDebt <= redemptionAmount) {
                p.amountProposed = currentSR.ercDebt;
            } else {
                p.amountProposed = redemptionAmount - p.totalAmountProposed;
                // @dev Exit when proposal would leave less than minShortErc, proxy for nearing end of slate
                if (currentSR.ercDebt - p.amountProposed < minShortErc) break;
            }

            /// At this point, the shortRecord passes all checks and will be included in the slate

            p.previousCR = p.currentCR;

            // @dev Cancel attached shortOrder if below minShortErc, regardless of ercDebt in SR
            // @dev All verified SR have ercDebt >= minShortErc so CR does not change in cancelShort()
            STypes.Order storage shortOrder = s.shorts[asset][p.shortOrderId];
            if (currentSR.status == SR.PartialFill && shortOrder.ercAmount < minShortErc) {
                if (shortOrder.shortRecordId != p.shortId || shortOrder.addr != p.shorter) revert Errors.InvalidShortOrder();
                LibOrders.cancelShort(asset, p.shortOrderId);
            }

            p.colRedeemed = p.oraclePrice.mulU88(p.amountProposed);
            if (p.colRedeemed > currentSR.collateral) {
                p.colRedeemed = currentSR.collateral;
            }

            currentSR.collateral -= p.colRedeemed;
            currentSR.ercDebt -= p.amountProposed;

            p.totalAmountProposed += p.amountProposed;
            p.totalColRedeemed += p.colRedeemed;

            // @dev directly write the properties of MTypes.ProposalData into bytes
            // instead of usual abi.encode to save on extra zeros being written
            slate = bytes.concat(
                slate,
                bytes20(p.shorter),
                bytes1(p.shortId),
                bytes8(uint64(p.currentCR)),
                bytes11(p.amountProposed),
                bytes11(p.colRedeemed)
            );

            LibSRUtil.disburseCollateral(p.asset, p.shorter, p.colRedeemed, currentSR.dethYieldRate, currentSR.updatedAt);
            p.redemptionCounter++;
            if (redemptionAmount - p.totalAmountProposed < minShortErc) break;
        }

        if (p.totalAmountProposed < minShortErc) revert Errors.RedemptionUnderMinShortErc();

        // @dev SSTORE2 the entire proposalData after validating proposalInput
        redeemerAssetUser.SSTORE2Pointer = SSTORE2.write(slate);
        redeemerAssetUser.slateLength = p.redemptionCounter;
        redeemerAssetUser.oraclePrice = p.oraclePrice;
        redeemerAssetUser.ercEscrowed -= p.totalAmountProposed;

        STypes.Asset storage Asset = s.asset[p.asset];
        Asset.ercDebt -= p.totalAmountProposed;

        uint32 protocolTime = LibOrders.getOffsetTime();
        redeemerAssetUser.timeProposed = protocolTime;
        // @dev Calculate the dispute period
        // @dev timeToDispute is immediate for shorts with CR <= 1.1x

        /*
        +-------+------------+
        | CR(X) |  Hours(Y)  |
        +-------+------------+
        | 1.1   |     0      |
        | 1.2   |    .333    |
        | 1.3   |    .75     |
        | 1.5   |    1.5     |
        | 1.7   |     3      |
        | 2.0   |     6      |
        +-------+------------+

        Creating fixed points and interpolating between points on the graph without using exponentials
        Using simple y = mx + b formula

        where x = currentCR - previousCR
        m = (y2-y1)/(x2-x1)
        b = previous fixed point (Y)
        */

        uint256 m;

        if (p.currentCR > 1.7 ether) {
            m = uint256(3 ether).div(0.3 ether);
            redeemerAssetUser.timeToDispute = protocolTime + uint32((m.mul(p.currentCR - 1.7 ether) + 3 ether) * 1 hours / 1 ether);
        } else if (p.currentCR > 1.5 ether) {
            m = uint256(1.5 ether).div(0.2 ether);
            redeemerAssetUser.timeToDispute =
                protocolTime + uint32((m.mul(p.currentCR - 1.5 ether) + 1.5 ether) * 1 hours / 1 ether);
        } else if (p.currentCR > 1.3 ether) {
            m = uint256(0.75 ether).div(0.2 ether);
            redeemerAssetUser.timeToDispute =
                protocolTime + uint32((m.mul(p.currentCR - 1.3 ether) + 0.75 ether) * 1 hours / 1 ether);
        } else if (p.currentCR > 1.2 ether) {
            m = uint256(0.417 ether).div(0.1 ether);
            redeemerAssetUser.timeToDispute =
                protocolTime + uint32((m.mul(p.currentCR - 1.2 ether) + C.ONE_THIRD) * 1 hours / 1 ether);
        } else if (p.currentCR > 1.1 ether) {
            m = uint256(C.ONE_THIRD.div(0.1 ether));
            redeemerAssetUser.timeToDispute = protocolTime + uint32(m.mul(p.currentCR - 1.1 ether) * 1 hours / 1 ether);
        }

        redeemerAssetUser.oraclePrice = p.oraclePrice;
        redeemerAssetUser.timeProposed = LibOrders.getOffsetTime();

        uint88 redemptionFee = calculateRedemptionFee(asset, p.totalColRedeemed, p.totalAmountProposed);
        if (redemptionFee > maxRedemptionFee) revert Errors.RedemptionFeeTooHigh();

        STypes.VaultUser storage VaultUser = s.vaultUser[Asset.vault][msg.sender];
        if (VaultUser.ethEscrowed < redemptionFee) revert Errors.InsufficientETHEscrowed();
        VaultUser.ethEscrowed -= redemptionFee;
        emit Events.ProposeRedemption(p.asset, msg.sender);
    }

    /**
     * @notice Challenge the proposed redemption candidates of a specific redeemer
     * @dev Fee is awarded based on ercDebt correctly disputed to encourage disputing bad proposals
     *
     * @param asset The market that will be impacted
     * @param redeemer Address of the redeemer
     * @param incorrectIndex Index of the proposal being disputed
     * @param disputeShorter Shorter address from the SR used to dispute the redeemer proposal
     * @param disputeShortId Id of the SR used to dispute the redeemer proposal
     *
     */
    function disputeRedemption(address asset, address redeemer, uint8 incorrectIndex, address disputeShorter, uint8 disputeShortId)
        external
        isNotFrozen(asset)
        nonReentrant
    {
        if (redeemer == msg.sender) revert Errors.CannotDisputeYourself();
        MTypes.DisputeRedemption memory d;
        d.asset = asset;
        d.redeemer = redeemer;

        STypes.AssetUser storage redeemerAssetUser = s.assetUser[d.asset][d.redeemer];
        if (redeemerAssetUser.SSTORE2Pointer == address(0)) revert Errors.InvalidRedemption();

        if (LibOrders.getOffsetTime() >= redeemerAssetUser.timeToDispute) revert Errors.TimeToDisputeHasElapsed();

        MTypes.ProposalData[] memory decodedProposalData =
            LibBytes.readProposalData(redeemerAssetUser.SSTORE2Pointer, redeemerAssetUser.slateLength);

        for (uint256 i = 0; i < decodedProposalData.length; i++) {
            if (decodedProposalData[i].shorter == disputeShorter && decodedProposalData[i].shortId == disputeShortId) {
                revert Errors.CannotDisputeWithRedeemerProposal();
            }
        }

        STypes.ShortRecord storage disputeSR = s.shortRecords[d.asset][disputeShorter][disputeShortId];
        // Match continue (skip) conditions in proposeRedemption()
        uint256 minShortErc = LibAsset.minShortErc(d.asset);
        if (!validRedemptionSR(disputeSR, d.redeemer, disputeShorter, minShortErc)) revert Errors.InvalidRedemption();

        MTypes.ProposalData memory incorrectProposal = decodedProposalData[incorrectIndex];
        MTypes.ProposalData memory currentProposal;
        STypes.Asset storage Asset = s.asset[d.asset];

        uint256 disputeCR = disputeSR.getCollateralRatio(redeemerAssetUser.oraclePrice);

        if (disputeCR < incorrectProposal.CR && disputeSR.updatedAt + C.DISPUTE_REDEMPTION_BUFFER <= redeemerAssetUser.timeProposed)
        {
            // @dev All proposals from the incorrectIndex onward will be removed
            // @dev Thus the proposer can only redeem a portion of their original slate
            for (uint256 i = incorrectIndex; i < decodedProposalData.length; i++) {
                currentProposal = decodedProposalData[i];

                STypes.ShortRecord storage currentSR = s.shortRecords[d.asset][currentProposal.shorter][currentProposal.shortId];
                currentSR.collateral += currentProposal.colRedeemed;
                currentSR.ercDebt += currentProposal.ercDebtRedeemed;

                d.incorrectCollateral += currentProposal.colRedeemed;
                d.incorrectErcDebt += currentProposal.ercDebtRedeemed;
            }

            s.vault[Asset.vault].dethCollateral += d.incorrectCollateral;
            Asset.dethCollateral += d.incorrectCollateral;
            Asset.ercDebt += d.incorrectErcDebt;

            // @dev Update the redeemer's SSTORE2Pointer
            if (incorrectIndex > 0) {
                redeemerAssetUser.slateLength = incorrectIndex;
            } else {
                // @dev this implies everything in the redeemer's proposal was incorrect
                delete redeemerAssetUser.SSTORE2Pointer;
                emit Events.DisputeRedemptionAll(d.asset, redeemer);
            }

            // @dev Penalty is based on the proposal with highest CR (decodedProposalData is sorted)
            // @dev PenaltyPct is bound between CallerFeePct and 33% to prevent exploiting primaryLiquidation fees
            uint256 penaltyPct = LibOrders.min(
                LibOrders.max(LibAsset.callerFeePct(d.asset), (currentProposal.CR - disputeCR).div(currentProposal.CR)), 0.33 ether
            );

            uint88 penaltyAmt = d.incorrectErcDebt.mulU88(penaltyPct);

            // @dev Give redeemer back ercEscrowed that is no longer used to redeem (penalty applied)
            redeemerAssetUser.ercEscrowed += (d.incorrectErcDebt - penaltyAmt);
            s.assetUser[d.asset][msg.sender].ercEscrowed += penaltyAmt;
        } else {
            revert Errors.InvalidRedemptionDispute();
        }
    }

    /**
     * @notice Claim the collateral from the verified redemption candidates
     * @dev Can only be called by the redeemer after the dispute period has passed
     *
     * @param asset The market that will be impacted
     *
     */
    function claimRedemption(address asset) external isNotFrozen(asset) nonReentrant {
        uint256 vault = s.asset[asset].vault;
        STypes.AssetUser storage redeemerAssetUser = s.assetUser[asset][msg.sender];
        STypes.VaultUser storage redeemerVaultUser = s.vaultUser[vault][msg.sender];
        if (redeemerAssetUser.SSTORE2Pointer == address(0)) revert Errors.InvalidRedemption();
        if (LibOrders.getOffsetTime() < redeemerAssetUser.timeToDispute) revert Errors.TimeToDisputeHasNotElapsed();

        MTypes.ProposalData[] memory decodedProposalData =
            LibBytes.readProposalData(redeemerAssetUser.SSTORE2Pointer, redeemerAssetUser.slateLength);

        uint88 totalColRedeemed;
        for (uint256 i = 0; i < decodedProposalData.length; i++) {
            MTypes.ProposalData memory currentProposal = decodedProposalData[i];
            totalColRedeemed += currentProposal.colRedeemed;
            _claimRemainingCollateral({
                asset: asset,
                vault: vault,
                shorter: currentProposal.shorter,
                shortId: currentProposal.shortId
            });
        }
        redeemerVaultUser.ethEscrowed += totalColRedeemed;
        delete redeemerAssetUser.SSTORE2Pointer;
        emit Events.ClaimRedemption(asset, msg.sender);
    }

    /**
     * @notice Claim the leftover collateral from a SR that has been fully redeemed
     * @dev Can only be called by the shorter after the dispute period has passed
     *
     * @param asset The market that will be impacted
     * @param redeemer Address of the redeemer
     * @param claimIndex Index of the proposal pointing to the shorter SR to be resolved
     * @param id Shorter address from the SR used to dispute the redeemer proposal
     *
     */
    // Redeemed shorters can call this to get their collateral back if redeemer does not claim
    function claimRemainingCollateral(address asset, address redeemer, uint8 claimIndex, uint8 id)
        external
        isNotFrozen(asset)
        nonReentrant
    {
        STypes.AssetUser storage redeemerAssetUser = s.assetUser[asset][redeemer];
        if (redeemerAssetUser.SSTORE2Pointer == address(0)) revert Errors.InvalidRedemption();
        if (redeemerAssetUser.timeToDispute > LibOrders.getOffsetTime()) revert Errors.TimeToDisputeHasNotElapsed();

        // @dev Only need to read up to the position of the SR to be claimed
        MTypes.ProposalData[] memory decodedProposalData =
            LibBytes.readProposalData(redeemerAssetUser.SSTORE2Pointer, claimIndex + 1);
        MTypes.ProposalData memory claimProposal = decodedProposalData[claimIndex];

        if (claimProposal.shorter != msg.sender && claimProposal.shortId != id) revert Errors.CanOnlyClaimYourShort();

        STypes.Asset storage Asset = s.asset[asset];
        _claimRemainingCollateral({asset: asset, vault: Asset.vault, shorter: msg.sender, shortId: id});
    }

    // Send leftover collateral back to shorter and close SR
    function _claimRemainingCollateral(address asset, uint256 vault, address shorter, uint8 shortId) private {
        STypes.ShortRecord storage shortRecord = s.shortRecords[asset][shorter][shortId];

        if (shortRecord.ercDebt == 0 && shortRecord.status == SR.FullyFilled) {
            // @dev Refund shorter the remaining collateral only if fully redeemed and not claimed already
            uint88 collateral = shortRecord.collateral;
            s.vaultUser[vault][shorter].ethEscrowed += collateral;
            // @dev Shorter shouldn't lose any unclaimed yield because dispute time > YIELD_DELAY_SECONDS
            LibSRUtil.disburseCollateral(asset, shorter, collateral, shortRecord.dethYieldRate, shortRecord.updatedAt);
            LibShortRecord.deleteShortRecord(asset, shorter, shortId);
        }
    }

    // @dev inspired by https://docs.liquity.org/faq/lusd-redemptions#how-is-the-redemption-fee-calculated
    function calculateRedemptionFee(address asset, uint88 colRedeemed, uint88 ercDebtRedeemed)
        internal
        returns (uint88 redemptionFee)
    {
        STypes.Asset storage Asset = s.asset[asset];
        uint32 protocolTime = LibOrders.getOffsetTime();
        uint256 secondsPassed = uint256((protocolTime - Asset.lastRedemptionTime)) * 1 ether;
        uint256 decayFactor = C.SECONDS_DECAY_FACTOR.pow(secondsPassed);
        uint256 decayedBaseRate = Asset.baseRate.mulU64(decayFactor);
        // @dev Calculate Asset.ercDebt prior to proposal
        uint104 totalAssetErcDebt = (ercDebtRedeemed + Asset.ercDebt).mulU104(C.BETA);
        // @dev Derived via this forumula: baseRateNew = baseRateOld + redeemedLUSD / (2 * totalLUSD)
        uint256 redeemedDUSDFraction = ercDebtRedeemed.div(totalAssetErcDebt);
        uint256 newBaseRate = decayedBaseRate + redeemedDUSDFraction;
        newBaseRate = LibOrders.min(newBaseRate, 1 ether); // cap baseRate at a maximum of 100%
        assert(newBaseRate > 0); // Base rate is always non-zero after redemption
        // Update the baseRate state variable
        Asset.baseRate = uint64(newBaseRate);
        Asset.lastRedemptionTime = protocolTime;
        uint256 redemptionRate = LibOrders.min((Asset.baseRate + 0.005 ether), 1 ether);
        return uint88(redemptionRate.mul(colRedeemed));
    }
}
"},"contracts/facets/SecondaryLiquidationFacet.sol":{"content":"// SPDX-License-Identifier: GPL-3.0-only
pragma solidity 0.8.21;

import {U256, U88, U80} from "contracts/libraries/PRBMathHelper.sol";

import {IAsset} from "interfaces/IAsset.sol";

import {Errors} from "contracts/libraries/Errors.sol";
import {Events} from "contracts/libraries/Events.sol";
import {STypes, MTypes, SR} from "contracts/libraries/DataTypes.sol";
import {Modifiers} from "contracts/libraries/AppStorage.sol";
import {LibAsset} from "contracts/libraries/LibAsset.sol";
import {LibOracle} from "contracts/libraries/LibOracle.sol";
import {LibOrders} from "contracts/libraries/LibOrders.sol";
import {LibShortRecord} from "contracts/libraries/LibShortRecord.sol";
import {LibSRUtil} from "contracts/libraries/LibSRUtil.sol";

// import {console} from "contracts/libraries/console.sol";

contract SecondaryLiquidationFacet is Modifiers {
    using LibShortRecord for STypes.ShortRecord;
    using U256 for uint256;
    using U88 for uint88;
    using U80 for uint80;

    /**
     * @notice Liquidates short using liquidator's ercEscrowed or wallet
     * @dev Secondary liquidation function
     * @dev Must liquidate all of the debt. No partial (unless TAPP short)
     *
     * @param asset The market that will be impacted
     * @param batches Array of shorters, shortRecordIds, and shortOrderIds to liquidate
     * @param liquidateAmount Amount of ercDebt to liquidate
     * @param isWallet Liquidate using wallet balance when true, ercEscrowed when false
     *
     */

    // @dev If you want to liquidated more than uint88.max worth of erc in shorts, you must call liquidateSecondary multiple times
    function liquidateSecondary(address asset, MTypes.BatchLiquidation[] memory batches, uint88 liquidateAmount, bool isWallet)
        external
        onlyValidAsset(asset)
        isNotFrozen(asset)
        nonReentrant
    {
        STypes.AssetUser storage AssetUser = s.assetUser[asset][msg.sender];
        MTypes.SecondaryLiquidation memory m;
        uint256 penaltyCR = LibAsset.penaltyCR(asset);
        uint256 oraclePrice = LibOracle.getSavedOrSpotOraclePrice(asset);
        uint256 liquidationCR = LibAsset.liquidationCR(asset);
        uint88 minShortErc = uint88(LibAsset.minShortErc(asset));

        uint88 liquidatorCollateral;
        uint88 liquidateAmountLeft = liquidateAmount;

        for (uint256 i; i < batches.length;) {
            m = _setLiquidationStruct(asset, batches[i], penaltyCR, oraclePrice);
            unchecked {
                ++i;
            }

            // If ineligible, skip to the next shortrecord instead of reverting
            if (
                m.shorter == msg.sender || m.cRatio > liquidationCR || m.short.status == SR.Closed || m.short.ercDebt == 0
                    || (m.shorter != address(this) && liquidateAmountLeft < m.short.ercDebt)
            ) {
                continue;
            }

            bool shortUnderMin;
            if (m.isPartialFill) {
                // Check attached shortOrder ercAmount left since SR will be fully liquidated
                STypes.Order storage shortOrder = s.shorts[m.asset][m.shortOrderId];
                shortUnderMin = shortOrder.ercAmount < minShortErc;
                if (shortUnderMin) {
                    // Skip instead of reverting for invalid shortOrder
                    if (shortOrder.shortRecordId != m.short.id || shortOrder.addr != m.shorter) {
                        continue;
                    }
                }
            }

            bool partialTappLiquidation;
            // Setup partial liquidation of TAPP short
            if (m.shorter == address(this)) {
                partialTappLiquidation = liquidateAmountLeft < m.short.ercDebt;
                if (partialTappLiquidation) {
                    m.short.ercDebt = liquidateAmountLeft;
                }
            }

            // Determine which secondary liquidation method to use
            if (isWallet) {
                IAsset tokenContract = IAsset(m.asset);
                uint256 walletBalance = tokenContract.balanceOf(msg.sender);
                if (walletBalance < m.short.ercDebt) continue;
                tokenContract.burnFrom(msg.sender, m.short.ercDebt);
                assert(tokenContract.balanceOf(msg.sender) < walletBalance);
            } else {
                if (AssetUser.ercEscrowed < m.short.ercDebt) {
                    continue;
                }
                AssetUser.ercEscrowed -= m.short.ercDebt;
            }

            if (partialTappLiquidation) {
                // Partial liquidation of TAPP short
                _secondaryLiquidationHelperPartialTapp(m);
            } else {
                // Full liquidation
                _secondaryLiquidationHelper(m);
            }

            // @dev cancels shortOrder of partialFilled SR
            if (shortUnderMin) {
                LibOrders.cancelShort(m.asset, m.shortOrderId);
            }

            // Update in memory for final state change after loops
            liquidatorCollateral += m.liquidatorCollateral;
            liquidateAmountLeft -= m.short.ercDebt;
            if (liquidateAmountLeft == 0) break;
        }

        if (liquidateAmount == liquidateAmountLeft) revert Errors.SecondaryLiquidationNoValidShorts();

        // Update finalized state changes
        {
            STypes.Asset storage Asset = s.asset[m.asset];
            Asset.ercDebt -= liquidateAmount - liquidateAmountLeft;
            s.vaultUser[Asset.vault][msg.sender].ethEscrowed += liquidatorCollateral;
        }
        emit Events.LiquidateSecondary(asset, batches, msg.sender, isWallet);
    }

    /**
     * @notice Sets the memory struct m with initial data
     *
     * @param asset The market that will be impacted
     * @param batch Struct of shorters, shortRecordIds, and shortOrderIds to liquidate
     *
     * @return m Memory struct used throughout PrimaryLiquidationFacet.sol
     */
    function _setLiquidationStruct(address asset, MTypes.BatchLiquidation memory batch, uint256 penaltyCR, uint256 oraclePrice)
        private
        returns (MTypes.SecondaryLiquidation memory m)
    {
        LibShortRecord.updateErcDebt(asset, batch.shorter, batch.shortId);

        m.short = s.shortRecords[asset][batch.shorter][batch.shortId];
        if (m.short.ercDebt == 0) return m; // @dev Early return ok, SR to be skipped since ineligible

        m.asset = asset;
        m.shorter = batch.shorter;
        m.penaltyCR = penaltyCR;
        m.cRatio = m.short.getCollateralRatio(oraclePrice);
        m.oraclePrice = oraclePrice;
        m.shortOrderId = batch.shortOrderId;
        m.isPartialFill = m.short.status == SR.PartialFill;
    }

    /**
     * @notice Handles accounting for secondary liquidation methods (wallet and ercEscrowed)
     *
     * @param m Memory struct used throughout PrimaryLiquidationFacet.sol
     *
     */
    // +----------------+---------------+---------+-------+
    // |     Cratio     |  Liquidator   | Shorter | Pool  |
    // +----------------+---------------+---------+-------+
    // | > 1.5          | (cannot call) | n/a     | n/a   |
    // | 1.1 < c <= 1.5 | 1             | c - 1   | 0     |
    // | 1.0 < c <= 1.1 | 1             | 0       | c - 1 |
    // | c <= 1         | c             | 0       | 0     |
    // +----------------+---------------+---------+-------+
    function _secondaryLiquidationHelper(MTypes.SecondaryLiquidation memory m) private {
        if (m.cRatio > 1 ether) {
            m.liquidatorCollateral = m.short.ercDebt.mulU88(m.oraclePrice); // eth

            // if cRatio > 110%, shorter gets remaining collateral
            // Otherwise they take a penalty, and remaining goes to the pool
            address remainingCollateralAddress = m.cRatio > m.penaltyCR ? m.shorter : address(this);

            s.vaultUser[s.asset[m.asset].vault][remainingCollateralAddress].ethEscrowed +=
                m.short.collateral - m.liquidatorCollateral;
        } else {
            m.liquidatorCollateral = m.short.collateral;
        }

        LibSRUtil.disburseCollateral(m.asset, m.shorter, m.short.collateral, m.short.dethYieldRate, m.short.updatedAt);
        LibShortRecord.deleteShortRecord(m.asset, m.shorter, m.short.id);
    }

    function min88(uint256 a, uint88 b) private pure returns (uint88) {
        if (a > type(uint88).max) revert Errors.InvalidAmount();
        return a < b ? uint88(a) : b;
    }

    function _secondaryLiquidationHelperPartialTapp(MTypes.SecondaryLiquidation memory m) private {
        STypes.ShortRecord storage short = s.shortRecords[m.asset][address(this)][m.short.id];
        // Update erc balance
        short.ercDebt -= m.short.ercDebt; // @dev m.short.ercDebt was updated earlier to equal erc filled
        // Update eth balance
        // @dev Need to use min if CR < 1
        m.liquidatorCollateral = min88(m.short.ercDebt.mul(m.oraclePrice), m.short.collateral);
        short.collateral -= m.liquidatorCollateral;
        LibSRUtil.disburseCollateral(m.asset, m.shorter, m.liquidatorCollateral, m.short.dethYieldRate, m.short.updatedAt);
    }
}
"},"contracts/facets/ShortOrdersFacet.sol":{"content":"// SPDX-License-Identifier: GPL-3.0-only
pragma solidity 0.8.21;

import {U256, U88, U80} from "contracts/libraries/PRBMathHelper.sol";

import {Errors} from "contracts/libraries/Errors.sol";
import {STypes, MTypes, O, SR} from "contracts/libraries/DataTypes.sol";
import {Modifiers} from "contracts/libraries/AppStorage.sol";
import {LibOrders} from "contracts/libraries/LibOrders.sol";
import {LibAsset} from "contracts/libraries/LibAsset.sol";
import {LibOracle} from "contracts/libraries/LibOracle.sol";
import {LibShortRecord} from "contracts/libraries/LibShortRecord.sol";
import {LibSRUtil} from "contracts/libraries/LibSRUtil.sol";
import {C} from "contracts/libraries/Constants.sol";

// import {console} from "contracts/libraries/console.sol";

contract ShortOrdersFacet is Modifiers {
    using U256 for uint256;
    using U88 for uint88;
    using U80 for uint80;

    /**
     * @notice Creates limit short in market system
     * @dev incomingShort created here instead of AskMatchAlgo to prevent stack too deep
     * @dev Shorts can only be limits
     *
     * @param asset The market that will be impacted
     * @param price Unit price in eth for erc sold
     * @param ercAmount Amount of erc minted and sold
     * @param orderHintArray Array of hint ID for gas-optimized sorted placement on market
     * @param shortHintArray Array of hint ID for gas-optimized short matching above oracle price
     * @param shortOrderCR Initial Collateral Ratio for a short order, between min/max, converted to uint8
     */
    function createLimitShort(
        address asset,
        uint80 price,
        uint88 ercAmount,
        MTypes.OrderHint[] memory orderHintArray,
        uint16[] memory shortHintArray,
        uint16 shortOrderCR
    ) external isNotFrozen(asset) onlyValidAsset(asset) nonReentrant {
        MTypes.CreateLimitShortParam memory p;
        STypes.Asset storage Asset = s.asset[asset];
        STypes.Order memory incomingShort;

        // @dev create "empty" SR. Fail early.
        incomingShort.shortRecordId = LibShortRecord.createShortRecord(asset, msg.sender, SR.Closed, 0, 0, 0, 0, 0);

        uint256 cr = LibOrders.convertCR(shortOrderCR);
        if ((shortOrderCR + C.BID_CR) < Asset.initialCR || cr >= C.CRATIO_MAX_INITIAL) {
            revert Errors.InvalidCR();
        }

        // @dev minShortErc needs to be modified (bigger) when cr < 1
        p.minShortErc = cr < 1 ether ? LibAsset.minShortErc(asset).mul(1 ether + cr.inv()) : LibAsset.minShortErc(asset);
        p.eth = price.mul(ercAmount);
        p.minAskEth = LibAsset.minAskEth(asset);
        if (ercAmount < p.minShortErc || p.eth < p.minAskEth) revert Errors.OrderUnderMinimumSize();

        // For a short, need enough collateral to cover minting ERC (calculated using initialCR)
        if (s.vaultUser[Asset.vault][msg.sender].ethEscrowed < p.eth.mul(cr)) revert Errors.InsufficientETHEscrowed();

        incomingShort.addr = msg.sender;
        incomingShort.price = price;
        incomingShort.ercAmount = ercAmount;
        incomingShort.id = Asset.orderIdCounter;
        incomingShort.orderType = O.LimitShort;
        incomingShort.creationTime = LibOrders.getOffsetTime();
        incomingShort.shortOrderCR = shortOrderCR; // 170 -> 1.70x

        p.startingId = s.bids[asset][C.HEAD].nextId;
        STypes.Order storage highestBid = s.bids[asset][p.startingId];
        // @dev if match and match price is gt .5% to saved oracle in either direction, update startingShortId
        if (highestBid.price >= incomingShort.price && highestBid.orderType == O.LimitBid) {
            LibOrders.updateOracleAndStartingShortViaThreshold(asset, LibOracle.getPrice(asset), incomingShort, shortHintArray);
        }

        p.oraclePrice = LibOracle.getSavedOrSpotOraclePrice(asset);
        if (LibSRUtil.checkRecoveryModeViolation(asset, cr, p.oraclePrice)) {
            revert Errors.BelowRecoveryModeCR();
        }

        // @dev reading spot oracle price
        if (incomingShort.price < p.oraclePrice) {
            LibOrders.addShort(asset, incomingShort, orderHintArray);
        } else {
            LibOrders.sellMatchAlgo(asset, incomingShort, orderHintArray, p.minAskEth);
        }
    }
}
"},"contracts/facets/ShortRecordFacet.sol":{"content":"// SPDX-License-Identifier: GPL-3.0-only
pragma solidity 0.8.21;

import {U256, U80, U88} from "contracts/libraries/PRBMathHelper.sol";

import {Errors} from "contracts/libraries/Errors.sol";
import {Events} from "contracts/libraries/Events.sol";
import {Modifiers} from "contracts/libraries/AppStorage.sol";
import {STypes, MTypes, SR} from "contracts/libraries/DataTypes.sol";
import {LibAsset} from "contracts/libraries/LibAsset.sol";
import {LibShortRecord} from "contracts/libraries/LibShortRecord.sol";
import {LibSRUtil} from "contracts/libraries/LibSRUtil.sol";
import {LibOrders} from "contracts/libraries/LibOrders.sol";
import {LibOracle} from "contracts/libraries/LibOracle.sol";
import {C} from "contracts/libraries/Constants.sol";

// import {console} from "contracts/libraries/console.sol";

contract ShortRecordFacet is Modifiers {
    using LibSRUtil for STypes.ShortRecord;
    using LibShortRecord for STypes.ShortRecord;
    using U256 for uint256;
    using U80 for uint80;
    using U88 for uint88;

    address private immutable dusd;

    constructor(address _dusd) {
        dusd = _dusd;
    }

    /**
     * @notice Increases collateral of an active short
     *
     * @param asset The market that will be impacted
     * @param id Id of short
     * @param amount Eth amount to increase collateral by
     *
     */
    function increaseCollateral(address asset, uint8 id, uint88 amount)
        external
        isNotFrozen(asset)
        nonReentrant
        onlyValidShortRecord(asset, msg.sender, id)
    {
        STypes.Asset storage Asset = s.asset[asset];
        uint256 vault = Asset.vault;
        STypes.Vault storage Vault = s.vault[vault];
        STypes.VaultUser storage VaultUser = s.vaultUser[vault][msg.sender];
        if (VaultUser.ethEscrowed < amount) revert Errors.InsufficientETHEscrowed();

        STypes.ShortRecord storage short = s.shortRecords[asset][msg.sender][id];
        short.updateErcDebt(asset);
        uint256 yield = short.collateral.mul(short.dethYieldRate);
        short.collateral += amount;

        uint256 cRatio = short.getCollateralRatioSpotPrice(asset);
        if (cRatio >= C.CRATIO_MAX) revert Errors.CollateralHigherThanMax();

        // Prevent flash loan
        short.updatedAt = LibOrders.getOffsetTime();

        yield += amount.mul(Vault.dethYieldRate);
        short.dethYieldRate = yield.divU80(short.collateral);

        VaultUser.ethEscrowed -= amount;
        Vault.dethCollateral += amount;
        Asset.dethCollateral += amount;
        emit Events.IncreaseCollateral(asset, msg.sender, id, amount);
    }

    /**
     * @notice Decrease collateral of an active short
     * @dev Cannot decrease below initialCR
     *
     * @param asset The market that will be impacted
     * @param id Id of short
     * @param amount Eth amount to decrease collateral by
     *
     */
    function decreaseCollateral(address asset, uint8 id, uint88 amount)
        external
        isNotFrozen(asset)
        nonReentrant
        onlyValidShortRecord(asset, msg.sender, id)
    {
        STypes.ShortRecord storage short = s.shortRecords[asset][msg.sender][id];
        short.updateErcDebt(asset);
        if (amount > short.collateral) revert Errors.InsufficientCollateral();

        short.collateral -= amount;

        uint256 oraclePrice = LibOracle.getSavedOrSpotOraclePrice(asset);
        uint256 cRatio = short.getCollateralRatio(oraclePrice);
        if (cRatio < LibAsset.initialCR(asset)) revert Errors.CRLowerThanMin();

        if (LibSRUtil.checkRecoveryModeViolation(asset, cRatio, oraclePrice)) revert Errors.BelowRecoveryModeCR();

        uint256 vault = s.asset[asset].vault;
        s.vaultUser[vault][msg.sender].ethEscrowed += amount;

        LibSRUtil.disburseCollateral(asset, msg.sender, amount, short.dethYieldRate, short.updatedAt);
        emit Events.DecreaseCollateral(asset, msg.sender, id, amount);
    }

    /**
     * @notice Combine active shorts into one short
     *
     * @param asset The market that will be impacted
     * @param ids Array of short ids to be combined
     *
     */
    function combineShorts(address asset, uint8[] memory ids, uint16[] memory shortOrderIds)
        external
        isNotFrozen(asset)
        nonReentrant
        onlyValidShortRecord(asset, msg.sender, ids[0])
    {
        if (shortOrderIds.length != ids.length) revert Errors.InvalidNumberOfShortOrderIds();

        if (ids.length < 2) revert Errors.InsufficientNumberOfShorts();
        // First short in the array
        STypes.ShortRecord storage firstShort = s.shortRecords[asset][msg.sender][ids[0]];
        // @dev Load initial short elements in struct to avoid stack too deep
        MTypes.CombineShorts memory c;
        c.asset = asset;
        c.shortUpdatedAt = firstShort.updatedAt;

        for (uint256 i = ids.length - 1; i > 0; i--) {
            uint8 _id = ids[i];
            STypes.ShortRecord storage currentShort = _onlyValidShortRecord(c.asset, msg.sender, _id);

            SR currentStatus = currentShort.status;

            // @dev Take latest time when combining shorts (prevent flash loan)
            if (currentShort.updatedAt > c.shortUpdatedAt) {
                c.shortUpdatedAt = currentShort.updatedAt;
            }

            {
                uint88 currentShortCollateral = currentShort.collateral;
                uint88 currentShortErcDebt = currentShort.ercDebt;
                c.collateral += currentShortCollateral;
                c.ercDebt += currentShortErcDebt;
                c.yield += currentShortCollateral.mul(currentShort.dethYieldRate);
                c.ercDebtSocialized += currentShortErcDebt.mul(currentShort.ercDebtRate);
            }

            if (currentShort.tokenId != 0) {
                // @dev First short should have NFT to prevent need for re-mint
                if (firstShort.tokenId == 0) revert Errors.FirstShortMustBeNFT();
            }

            // Cancel this short and combine with short in ids[0]
            LibShortRecord.deleteShortRecord(c.asset, msg.sender, _id);

            // @dev partialFill shorts must be cancelled in combineShorts regardless of SR/short Order debt levels
            LibSRUtil.checkCancelShortOrder(c.asset, currentStatus, shortOrderIds[i], ids[i], msg.sender);
        }

        // Ensure the base shortRecord was not included in the array twice and therefore deleted
        if (firstShort.status == SR.Closed) revert Errors.FirstShortDeleted();

        // Merge all short records into the short at position id[0]
        firstShort.merge(c.ercDebt, c.ercDebtSocialized, c.collateral, c.yield, c.shortUpdatedAt);

        // Realize debt accounting before checking for flags
        firstShort.updateErcDebt(c.asset);

        emit Events.CombineShorts(c.asset, msg.sender, ids);
    }
}
"},"contracts/facets/TWAPFacet.sol":{"content":"// SPDX-License-Identifier: GPL-3.0-only
pragma solidity 0.8.21;

import {C} from "contracts/libraries/Constants.sol";
import {OracleLibrary} from "contracts/libraries/UniswapOracleLibrary.sol";

// import {console} from "contracts/libraries/console.sol";

contract TWAPFacet {
    // @dev Computes arithmetic mean of prices between current time and x seconds ago.
    // @dev Uses parts of underlying code for OracleLibrary.consult()
    function estimateWETHInUSDC(uint128 amountIn, uint32 secondsAgo) external view returns (uint256 amountOut) {
        return OracleLibrary.estimateTWAP({
            amountIn: amountIn,
            secondsAgo: secondsAgo,
            pool: C.USDC_WETH,
            baseToken: C.WETH,
            quoteToken: C.USDC
        });
    }
}
"},"contracts/facets/TestFacet.sol":{"content":"// SPDX-License-Identifier: GPL-3.0-only
pragma solidity 0.8.21;

import {STypes, O, F} from "contracts/libraries/DataTypes.sol";
import {Modifiers} from "contracts/libraries/AppStorage.sol";
import {LibOracle} from "contracts/libraries/LibOracle.sol";
import {LibBridgeRouter} from "contracts/libraries/LibBridgeRouter.sol";
import {LibOrders} from "contracts/libraries/LibOrders.sol";
import {LibAsset} from "contracts/libraries/LibAsset.sol";
import {Errors} from "contracts/libraries/Errors.sol";
import {LibBridge} from "contracts/libraries/LibBridge.sol";
import {C, VAULT} from "contracts/libraries/Constants.sol";

import {TestTypes} from "test/utils/TestTypes.sol";
// import {console} from "contracts/libraries/console.sol";

// @dev dev-only
contract TestFacet is Modifiers {
    using LibOrders for mapping(address => mapping(uint16 => STypes.Order));

    address private immutable baseAsset;

    constructor(address asset) {
        baseAsset = asset;
    }

    function setFrozenT(address asset, F value) external {
        s.asset[asset].frozen = value;
    }

    // @dev same as OwnerFacet.setLiquidationCR without requires for testing
    function setLiquidationCRT(address asset, uint16 value) external {
        s.asset[asset].liquidationCR = value;
    }

    function getAskKey(address asset, uint16 id) external view returns (uint16 prevId, uint16 nextId) {
        return (s.asks[asset][id].prevId, s.asks[asset][id].nextId);
    }

    function getBidKey(address asset, uint16 id) external view returns (uint16 prevId, uint16 nextId) {
        return (s.bids[asset][id].prevId, s.bids[asset][id].nextId);
    }

    function getBidOrder(address asset, uint16 id) external view returns (STypes.Order memory bid) {
        return s.bids[asset][id];
    }

    function getAskOrder(address asset, uint16 id) external view returns (STypes.Order memory ask) {
        return s.asks[asset][id];
    }

    function getShortOrder(address asset, uint16 id) external view returns (STypes.Order memory short) {
        return s.shorts[asset][id];
    }

    function currentInactiveBids(address asset) external view returns (STypes.Order[] memory) {
        uint16 currentId = s.bids[asset][C.HEAD].prevId;
        uint256 orderSize;

        while (currentId != C.HEAD) {
            orderSize++;
            currentId = s.bids[asset][currentId].prevId;
        }

        STypes.Order[] memory orderArr = new STypes.Order[](orderSize);
        currentId = s.bids[asset][C.HEAD].prevId; // reset currentId

        for (uint256 i = 0; i < orderSize; i++) {
            orderArr[i] = s.bids[asset][currentId];
            currentId = orderArr[i].prevId;
        }
        return orderArr;
    }

    function currentInactiveAsks(address asset) external view returns (STypes.Order[] memory) {
        uint16 currentId = s.asks[asset][C.HEAD].prevId;
        uint256 orderSize;

        while (currentId != C.HEAD) {
            orderSize++;
            currentId = s.asks[asset][currentId].prevId;
        }

        STypes.Order[] memory orderArr = new STypes.Order[](orderSize);
        currentId = s.asks[asset][C.HEAD].prevId; // reset currentId

        for (uint256 i = 0; i < orderSize; i++) {
            orderArr[i] = s.asks[asset][currentId];
            currentId = orderArr[i].prevId;
        }
        return orderArr;
    }

    // @dev unused
    // function currentInactiveShorts(address asset) external view returns (STypes.Order[] memory) {
    //     uint16 currentId = s.shorts[asset][C.HEAD].prevId;
    //     uint256 orderSize;

    //     while (currentId != C.HEAD) {
    //         orderSize++;
    //         currentId = s.shorts[asset][currentId].prevId;
    //     }

    //     STypes.Order[] memory orderArr = new STypes.Order[](orderSize);
    //     currentId = s.shorts[asset][C.HEAD].prevId; // reset currentId

    //     for (uint256 i = 0; i < orderSize; i++) {
    //         orderArr[i] = s.shorts[asset][currentId];
    //         currentId = orderArr[i].prevId;
    //     }
    //     return orderArr;
    // }

    function setReentrantStatus(uint8 reentrantStatus) external {
        s.reentrantStatus = reentrantStatus;
    }

    function getReentrantStatus() external view returns (uint256) {
        return s.reentrantStatus;
    }

    function getAssetNormalizedStruct(address asset) external view returns (TestTypes.AssetNormalizedStruct memory) {
        return TestTypes.AssetNormalizedStruct({
            frozen: s.asset[asset].frozen,
            orderId: s.asset[asset].orderIdCounter,
            initialCR: LibAsset.initialCR(asset),
            liquidationCR: LibAsset.liquidationCR(asset),
            forcedBidPriceBuffer: LibAsset.forcedBidPriceBuffer(asset),
            penaltyCR: LibAsset.penaltyCR(asset),
            tappFeePct: LibAsset.tappFeePct(asset),
            callerFeePct: LibAsset.callerFeePct(asset),
            startingShortId: s.asset[asset].startingShortId,
            minBidEth: LibAsset.minBidEth(asset),
            minAskEth: LibAsset.minAskEth(asset),
            minShortErc: LibAsset.minShortErc(asset),
            assetId: s.asset[asset].assetId,
            recoveryCR: LibAsset.recoveryCR(asset)
        });
    }

    function getBridgeNormalizedStruct(address bridge) external view returns (TestTypes.BridgeNormalizedStruct memory) {
        return TestTypes.BridgeNormalizedStruct({withdrawalFee: LibBridge.withdrawalFee(bridge)});
    }

    function getWithdrawalFeePct(uint256 bridgePointer, address rethBridge, address stethBridge) external view returns (uint256) {
        return LibBridgeRouter.withdrawalFeePct(bridgePointer, rethBridge, stethBridge);
    }

    function setBaseOracle(address _oracle) external {
        s.baseOracle = _oracle;
    }

    // @dev used for gas testing
    function setOracleTimeAndPrice(address asset, uint256 price) external {
        LibOracle.setPriceAndTime(asset, price, LibOrders.getOffsetTime());
    }

    function getOracleTimeT(address asset) external view returns (uint256 oracleTime) {
        return LibOracle.getTime(asset);
    }

    function getOraclePriceT(address asset) external view returns (uint80 oraclePrice) {
        return LibOracle.getPrice(asset);
    }

    // @dev used to test shortHintId
    function setStartingShortId(address asset, uint16 id) external {
        s.asset[asset].startingShortId = id;
    }

    function updateStartingShortId(address asset, uint16[] calldata shortHintArray) external {
        LibOrders.updateOracleAndStartingShortViaTimeBidOnly(asset, shortHintArray);
    }

    // @dev used to test shortHintId
    function setDethYieldRate(uint256 vault, uint256 value) external {
        s.vault[vault].dethYieldRate = uint80(value);
    }

    function nonZeroVaultSlot0(uint256 vault) external {
        s.vault[vault].dethYieldRate += 1;
    }

    function setforcedBidPriceBufferT(address asset, uint8 value) external {
        s.asset[asset].forcedBidPriceBuffer = value;
    }

    function setErcDebtRate(address asset, uint64 value) external {
        s.asset[asset].ercDebtRate = value;
    }

    function setOrderIdT(address asset, uint16 value) external {
        s.asset[asset].orderIdCounter = value;
    }

    function setEthEscrowed(address addr, uint88 eth) external {
        s.vaultUser[VAULT.ONE][addr].ethEscrowed = eth;
    }

    function setBridgeCredit(address addr, uint88 bridgeCreditReth, uint88 bridgeCreditSteth) external {
        s.vaultUser[VAULT.ONE][addr].bridgeCreditReth = bridgeCreditReth;
        s.vaultUser[VAULT.ONE][addr].bridgeCreditSteth = bridgeCreditSteth;
    }

    function getUserOrders(address asset, address addr, O orderType) external view returns (STypes.Order[] memory orders) {
        STypes.Order[] memory allOrders;

        if (orderType == O.LimitBid) {
            allOrders = s.bids.currentOrders(asset);
        } else if (orderType == O.LimitAsk) {
            allOrders = s.asks.currentOrders(asset);
        } else if (orderType == O.LimitShort) {
            allOrders = s.shorts.currentOrders(asset);
        }
        uint256 counter = 0;

        for (uint256 i = 0; i < allOrders.length; i++) {
            if (allOrders[i].addr == addr) counter++;
        }

        orders = new STypes.Order[](counter);
        counter = 0;

        for (uint256 i = 0; i < allOrders.length; i++) {
            if (allOrders[i].addr == addr) {
                orders[counter] = allOrders[i];
                counter++;
            }
        }
        return orders;
    }

    function getAssets() external view returns (address[] memory) {
        return s.assets;
    }

    function getAssetsMapping(uint256 assetId) external view returns (address) {
        return s.assetMapping[assetId];
    }

    function setTokenId(uint40 tokenId) external {
        s.tokenIdCounter = tokenId;
    }

    function getTokenId() external view returns (uint40 tokenId) {
        return s.tokenIdCounter;
    }

    function getNFT(uint256 tokenId) external view returns (STypes.NFT memory nft) {
        return s.nftMapping[tokenId];
    }

    function getNFTName() external view returns (string memory) {
        return s.name;
    }

    function getNFTSymbol() external view returns (string memory) {
        return s.symbol;
    }

    function dittoShorterRate(uint256 vault) external view returns (uint256) {
        return (uint256(s.vault[vault].dittoShorterRate) * 1 ether) / C.TWO_DECIMAL_PLACES;
    }

    function dittoMatchedRate(uint256 vault) external view returns (uint256) {
        return (uint256(s.vault[vault].dittoMatchedRate) * 1 ether) / C.TWO_DECIMAL_PLACES;
    }

    function deleteBridge(address bridge) external onlyDAO {
        uint256 vault = s.bridge[bridge].vault;
        if (vault == 0) revert Errors.InvalidBridge();

        address[] storage VaultBridges = s.vaultBridges[vault];
        uint256 length = VaultBridges.length;
        for (uint256 i; i < length; i++) {
            if (VaultBridges[i] == bridge) {
                if (i != length - 1) {
                    VaultBridges[i] = VaultBridges[length - 1];
                }
                VaultBridges.pop();
                break;
            }
        }
        delete s.bridge[bridge];
    }

    //When deactivating an asset make sure to zero out the oracle.
    function setAssetOracle(address asset, address oracle) external onlyDAO {
        s.asset[asset].oracle = oracle;
    }

    function setErcDebt(address asset, address shorter, uint8 id, uint88 value) external {
        s.shortRecords[asset][shorter][id].ercDebt = value;
    }

    function setLastRedemptionTime(address asset, uint32 lastRedemptionTime) external {
        s.asset[asset].lastRedemptionTime = lastRedemptionTime;
    }

    function setBaseRate(address asset, uint64 baseRate) external {
        s.asset[asset].baseRate = baseRate;
    }

    function setMinShortErcT(address asset, uint16 value) external {
        s.asset[asset].minShortErc = value;
    }
}
