pragma solidity 0.8.21;

import {Errors, stdError, IDiamond, IDiamondCut, RemovedFunctions, UpgradeDiamondCut02} from "./02_upgrade_diamondCut.s.sol";
import {IDiamondLoupe} from "contracts/interfaces/IDiamondLoupe.sol";

contract UpgradeDiamond02Test is UpgradeDiamondCut02 {
    function setUp() public virtual override {
        super.setUp();
    }

    function testFork_Migration_02() public {
        RemovedFunctions removedFunctions = RemovedFunctions(_diamond);

        IDiamondLoupe.Facet[] memory facets = diamond.facets();

        uint256 selectorCount = 0;
        uint256 ownerFacetCount = 0;
        uint256 oldDiamondCutCount = 0;
        for (uint256 i = 0; i < facets.length; i++) {
            selectorCount += facets[i].functionSelectors.length;
            if (facets[i].facetAddress == address(0xCc7C8Eb5aDdEc694fC2EB29ae6c762D9ebCC9deb)) {
                ownerFacetCount = facets[i].functionSelectors.length;
                bool selectorPresent = false;
                for (uint256 x = 0; x < facets[i].functionSelectors.length; x++) {
                    if (facets[i].functionSelectors[x] == RemovedFunctions.setUnstakeFee.selector) {
                        selectorPresent = true;
                    }
                }
                if (selectorPresent == false) revert();
            } else if (facets[i].facetAddress == address(0xe518176203D28b8E556C9d3CdE1039aeFDb81f3a)) {
                oldDiamondCutCount = facets[i].functionSelectors.length;
                bool selectorPresent = false;
                for (uint256 x = 0; x < facets[i].functionSelectors.length; x++) {
                    if (facets[i].functionSelectors[x] == IDiamondCut.diamondCut.selector) {
                        selectorPresent = true;
                    }
                }
                if (selectorPresent == false) revert();
            }
        }
        assertTrue(ownerFacetCount > 0);
        assertTrue(oldDiamondCutCount > 0);

        assertEq(selectorCount, 113);
        assertEq(ownerFacetCount, 28);
        facetCut.push(
            IDiamondCut.FacetCut({
                facetAddress: address(0),
                action: IDiamondCut.FacetCutAction.Remove,
                functionSelectors: removeSelectors
            })
        );

        vm.prank(_safeWallet);
        //error is caused by a bug in diamondCut due to how solidity 0.8 handles over/underflows
        vm.expectRevert(stdError.arithmeticError);
        diamond.diamondCut(facetCut, address(0), "");

        vm.expectRevert(Errors.NotOwnerOrAdmin.selector);
        removedFunctions.setUnstakeFee(_bridgeSteth, 1);

        bytes memory diamondCutBytecode = getBytecode(DIAMOND_CUT_PATH);

        vm.prank(_dittoDeployer);
        address _newDiamondCut = create2Factory.safeCreate2(DIAMONDCUT_SALT, abi.encodePacked(diamondCutBytecode));

        assertEq(_newDiamondCut, address(0xd40f94e5fD70835AC6FC0f0eaf00AEb20767A4E8));

        facetCut[0] = IDiamondCut.FacetCut({
            facetAddress: _newDiamondCut,
            action: IDiamondCut.FacetCutAction.Replace,
            functionSelectors: replaceSelectors
        });
        vm.prank(_safeWallet);
        diamond.diamondCut(facetCut, address(0), "");

        facetCut[0] = IDiamondCut.FacetCut({
            facetAddress: address(0),
            action: IDiamondCut.FacetCutAction.Remove,
            functionSelectors: removeSelectors
        });
        vm.prank(_safeWallet);
        diamond.diamondCut(facetCut, address(0), "");

        vm.expectRevert(abi.encodeWithSignature("FunctionNotFound(bytes4)", RemovedFunctions.setUnstakeFee.selector));
        removedFunctions.setUnstakeFee(_bridgeSteth, 1);

        facets = diamond.facets();

        selectorCount = 0;
        ownerFacetCount = 0;
        uint256 newDiamondCutCount = 0;
        for (uint256 i = 0; i < facets.length; i++) {
            selectorCount += facets[i].functionSelectors.length;
            if (
                facets[i]
                    //existing owner facet
                    .facetAddress == address(0xCc7C8Eb5aDdEc694fC2EB29ae6c762D9ebCC9deb)
            ) {
                ownerFacetCount = facets[i].functionSelectors.length;
                bool selectorPresent = false;
                for (uint256 x = 0; x < facets[i].functionSelectors.length; x++) {
                    if (facets[i].functionSelectors[x] == RemovedFunctions.setUnstakeFee.selector) {
                        selectorPresent = true;
                    }
                }
                if (selectorPresent == true) revert();
            } else if (
                facets[i]
                    // old diamond cut facet
                    .facetAddress == address(0xe518176203D28b8E556C9d3CdE1039aeFDb81f3a)
            ) {
                revert();
            } else if (
                facets[i]
                    // new diamond cut facet
                    .facetAddress == address(0xd40f94e5fD70835AC6FC0f0eaf00AEb20767A4E8)
            ) {
                newDiamondCutCount = facets[i].functionSelectors.length;
                bool selectorPresent = false;
                for (uint256 x = 0; x < facets[i].functionSelectors.length; x++) {
                    if (facets[i].functionSelectors[x] == IDiamondCut.diamondCut.selector) {
                        selectorPresent = true;
                    }
                }
                if (selectorPresent == false) revert();
            }
        }

        assertTrue(ownerFacetCount > 0);
        assertTrue(newDiamondCutCount > 0);

        assertEq(selectorCount, 112);
        assertEq(ownerFacetCount, 27);
    }
}
"},"deploy/migrations/03_deploy_dao/03_deploy_dao.s.sol":{"content":"// SPDX-License-Identifier: GPL-3.0-only
pragma solidity 0.8.21;

//some imports are used through inheritance
import {Errors, stdError, IDiamond, IDiamondCut, console, MigrationHelper} from "deploy/migrations/MigrationHelper.sol";

interface RemovedFunctions {
    function setAssetOracle(address, address) external;
}

// FOUNDRY_PROFILE=deploy-mainnet forge script DeployDao03 --ffi
contract DeployDao03 is MigrationHelper {
    bytes32 internal constant DEFAULT_ADMIN_ROLE = 0x00;
    bytes32 internal TIMELOCK_SALT = bytes32(0x000000000000000000000000000000000000000093ed3189d3ff000000084072);
    bytes32 internal GOVERNOR_SALT = bytes32(0x0000000000000000000000000000000000000000bfc7db13a2f1c000013d0f55);
    address[] internal proposers = [_safeWallet];
    address[] internal executors = [_safeWallet];
    address internal admin = _safeWallet;
    bytes internal timelockInitcode;
    address internal timelockAddress;
    bytes internal governorInitcode;
    address internal governorAddress;
    bytes internal claimOwnerPayload;

    bytes4[] internal removeSelectors = [RemovedFunctions.setAssetOracle.selector];
    bytes internal diamondCutPayload;

    // fork and initialize variables shared between the script and test
    function setUp() public virtual {
        fork(18821534);
        //timelock
        bytes memory timelockBytecode = getBytecode("03_deploy_dao/DittoTimelockController.json");
        timelockInitcode = abi.encodePacked(timelockBytecode, abi.encode(proposers, executors, admin));
        timelockAddress = create2Factory.findCreate2Address(TIMELOCK_SALT, timelockInitcode);
        //governor
        bytes memory governorBytecode = getBytecode("03_deploy_dao/DittoGovernor.json");
        governorInitcode = abi.encodePacked(governorBytecode, abi.encode(_ditto, timelockAddress));
        governorAddress = create2Factory.findCreate2Address(GOVERNOR_SALT, governorInitcode);

        claimOwnerPayload = abi.encodeWithSelector(IDiamond.claimOwnership.selector);

        facetCut.push(
            IDiamondCut.FacetCut({
                facetAddress: address(0),
                action: IDiamondCut.FacetCutAction.Remove,
                functionSelectors: removeSelectors
            })
        );

        diamondCutPayload = abi.encodeWithSelector(IDiamond.diamondCut.selector, facetCut, address(0), "");
    }

    function run() external {
        // console.log("init code hash for timelock salt generation");
        // emit log_bytes32(keccak256(timelockInitcode));

        //deploy timelock
        bytes memory safeCreate2 = abi.encodeWithSelector(create2Factory.safeCreate2.selector, TIMELOCK_SALT, timelockInitcode);
        console.log("----------------------------------------------------");
        console.log("batch 1 - timelock safeCreate2 txn data");
        console.log("to address: ", _immutableCreate2Factory);
        console.newLine();
        emit log_bytes(safeCreate2);
        console.newLine();

        // console.log("----------------------------------------------------");
        // console.log("init code hash for governor salt generation");
        // emit log_bytes32(keccak256(governorInitcode));

        //deploy governor
        safeCreate2 = abi.encodeWithSelector(create2Factory.safeCreate2.selector, GOVERNOR_SALT, governorInitcode);
        console.log("----------------------------------------------------");
        console.log("batch 2 - governor safeCreate2 txn data");
        console.log("to address: ", _immutableCreate2Factory);
        console.newLine();
        emit log_bytes(safeCreate2);
        console.newLine();

        //grant roles
        bytes memory grantRole = abi.encodeWithSelector(timelock.grantRole.selector, EXECUTOR_ROLE, _governor);
        console.log("----------------------------------------------------");
        console.log("batch 3 - grant executor to governor txn data");
        console.log("to address: ", _timelock);
        console.newLine();
        emit log_bytes(grantRole);
        console.newLine();

        grantRole = abi.encodeWithSelector(timelock.grantRole.selector, PROPOSER_ROLE, _governor);
        console.log("----------------------------------------------------");
        console.log("batch 3 - grant proposer to governor txn data");
        console.log("to address: ", _timelock);
        console.newLine();
        emit log_bytes(grantRole);
        console.newLine();

        grantRole = abi.encodeWithSelector(timelock.grantRole.selector, EXECUTOR_ROLE, _timelock);
        console.log("----------------------------------------------------");
        console.log("batch 3 - grant executor to timelock txn data");
        console.log("to address: ", _timelock);
        console.newLine();
        emit log_bytes(grantRole);
        console.newLine();

        //renounce role
        bytes memory renounceRole = abi.encodeWithSelector(timelock.renounceRole.selector, DEFAULT_ADMIN_ROLE, _safeWallet);
        console.log("----------------------------------------------------");
        console.log("batch 3 - renounce timelock admin txn data");
        console.log("to address: ", _timelock);
        console.newLine();
        emit log_bytes(renounceRole);
        console.newLine();

        //diamond cut remove setAssetOracle
        //differs from test because in tests this is a governance proposal to test out governor/timelock
        console.log("----------------------------------------------------");
        console.log("batch 3 - diamondCut remove setAssetOracle txn data");
        console.log("to address: ", _diamond);
        console.newLine();
        emit log_bytes(diamondCutPayload);
        console.newLine();

        //transfer diamond ownership
        bytes memory transferOwnership = abi.encodeWithSelector(diamond.transferOwnership.selector, _timelock);
        console.log("----------------------------------------------------");
        console.log("batch 3 - transfer diamond ownership txn data");
        console.log("to address: ", _diamond);
        console.newLine();
        emit log_bytes(transferOwnership);
        console.newLine();

        //timelock schedule claimOwner
        bytes memory timelockSchedule =
            abi.encodeWithSelector(timelock.schedule.selector, _diamond, 0, claimOwnerPayload, bytes32(0), bytes32(0), 0);
        console.log("----------------------------------------------------");
        console.log("batch 4 - timelock schedule claim ownership txn data");
        console.log("to address: ", _timelock);
        console.newLine();
        emit log_bytes(timelockSchedule);
        console.newLine();

        //timelock execute claimOwner
        bytes memory timelockExecute =
            abi.encodeWithSelector(timelock.execute.selector, _diamond, 0, claimOwnerPayload, bytes32(0), bytes32(0), 0);
        console.log("----------------------------------------------------");
        console.log("batch 4 - timelock execute claim ownership txn data");
        console.log("to address: ", _timelock);
        console.newLine();
        emit log_bytes(timelockExecute);
        console.newLine();

        //send DAO funds to timelock
        bytes memory dittoTransfer = abi.encodeWithSelector(ditto.transfer.selector, _timelock, 35_000_000 ether);
        console.log("----------------------------------------------------");
        console.log("batch 4 - send DAO funds to timelock");
        console.log("to address: ", _ditto);
        console.newLine();
        emit log_bytes(dittoTransfer);
        console.newLine();
    }
}
"},"deploy/migrations/03_deploy_dao/03_deploy_dao.t.sol":{"content":"// SPDX-License-Identifier: GPL-3.0-only
pragma solidity 0.8.21;

import {Errors, stdError, IDiamond, IDiamondCut, RemovedFunctions, console, DeployDao03} from "./03_deploy_dao.s.sol";

contract DeployDao03Test is DeployDao03 {
    function setUp() public virtual override {
        super.setUp();
    }

    function testFork_Migration_03() public {
        //deploy timelock with 0xD1770 prefix
        address deployedTimelockAddress = create2Factory.safeCreate2(TIMELOCK_SALT, timelockInitcode);
        assertEq(deployedTimelockAddress, timelockAddress);
        assertEq(deployedTimelockAddress, _timelock);

        //deploy governor with 0xD1770 prefix
        address deployedGovernorAddress = create2Factory.safeCreate2(GOVERNOR_SALT, governorInitcode);
        assertEq(deployedGovernorAddress, governorAddress);
        assertEq(deployedGovernorAddress, _governor);

        vm.startPrank(_safeWallet);
        //grant roles
        timelock.grantRole(EXECUTOR_ROLE, _governor);
        timelock.grantRole(PROPOSER_ROLE, _governor);
        //this is necessary because of GovernorTimelockControl module
        timelock.grantRole(EXECUTOR_ROLE, _timelock);
        //renounce admin role
        timelock.renounceRole(DEFAULT_ADMIN_ROLE, _safeWallet);

        //admin role renounced
        vm.expectRevert(abi.encodeWithSignature("AccessControlUnauthorizedAccount(address,bytes32)", _safeWallet, bytes32(0)));
        //governor should not be given canceller until future
        timelock.grantRole(CANCELLER_ROLE, _governor);

        //transfer ownership of diamond to timelock
        diamond.transferOwnership(_timelock);
        //ditto safe wallet can propose to timelock operation
        timelock.schedule(_diamond, 0, claimOwnerPayload, bytes32(0), bytes32(0), 0);

        //ditto safe wallet can cancel timelock operation
        timelock.cancel(timelock.hashOperation(_diamond, 0, claimOwnerPayload, bytes32(0), bytes32(0)));

        timelock.schedule(_diamond, 0, claimOwnerPayload, bytes32(0), bytes32(0), 0);
        //ditto safe wallet can execute timelock txns
        timelock.execute(_diamond, 0, claimOwnerPayload, bytes32(0), bytes32(0));
        assertEq(diamond.owner(), _timelock);

        //ownership transferred from safeWallet
        vm.expectRevert("LibDiamond: Must be contract owner");
        diamond.diamondCut(facetCut, address(0), "");

        timelock.schedule(_diamond, 0, diamondCutPayload, bytes32(0), bytes32(0), 0);

        bytes memory cancelPayload = abi.encodeWithSelector(
            timelock.cancel.selector, timelock.hashOperation(_diamond, 0, diamondCutPayload, bytes32(0), bytes32(0))
        );

        targets.push(_timelock);
        values.push(0);
        calldatas.push(cancelPayload);

        //must self-delegate to get voting power.
        ditto.delegate(_safeWallet);
        vm.roll(block.number + 1);

        uint256 proposalId = governor.propose(targets, values, calldatas, "cancel diamondCut");

        //skip 1 day to bypass voting delay
        vm.roll(block.number + 7201);

        governor.castVote(proposalId, 1);

        vm.roll(block.number + 50_401);

        governor.queue(targets, values, calldatas, keccak256("cancel diamondCut"));
        //governor cannot cancel scheduled timelock txn
        vm.expectRevert(abi.encodeWithSignature("AccessControlUnauthorizedAccount(address,bytes32)", _timelock, CANCELLER_ROLE));
        governor.execute(targets, values, calldatas, keccak256("cancel diamondCut"));

        bytes memory executePayload =
            abi.encodeWithSelector(timelock.execute.selector, _diamond, 0, diamondCutPayload, bytes32(0), bytes32(0));

        targets[0] = _timelock;
        values[0] = 0;
        calldatas[0] = executePayload;

        proposalId = governor.propose(targets, values, calldatas, "diamondCut remove setAssetOracle");

        vm.roll(block.number + 7201);
        governor.castVote(proposalId, 1);
        vm.roll(block.number + 50_401);

        governor.queue(targets, values, calldatas, keccak256("diamondCut remove setAssetOracle"));

        //function exists

        vm.expectRevert("LibDiamond: Must be contract owner");
        RemovedFunctions(_diamond).setAssetOracle(_dusd, address(0));

        governor.execute(targets, values, calldatas, keccak256("diamondCut remove setAssetOracle"));

        //function doesn't exist on diamond
        vm.expectRevert(abi.encodeWithSignature("FunctionNotFound(bytes4)", RemovedFunctions.setAssetOracle.selector));
        RemovedFunctions(_diamond).setAssetOracle(_dusd, address(0));

        //transfer DAO funds (35%) to timelock
        assertEq(ditto.balanceOf(_safeWallet), 70_000_000 ether);
        ditto.transfer(_timelock, 35_000_000 ether);
        assertEq(ditto.balanceOf(_timelock), 35_000_000 ether);
        assertEq(ditto.balanceOf(_safeWallet), 35_000_000 ether);

        vm.stopPrank();
    }
}
